quests[24576] = { id = 24576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine nette Unterhaltung...", description = "<Roka hört widerwillig zu, als Ihr ihr erzählt, warum Ihr versucht, Flenni aufzuspüren.>\n\nIhr meint also, ich hätte die ganze Zeit unter dem Einfluss eines Alchemisten gestanden? Ich kann nicht glauben, dass ich auf diesen Schwindel hereingefallen bin! Wenn ich diesen hinterhältigen Goblin jemals in die Finger kriege, reiß ich ihn in Stücke!\n\nFalls er mit seinen Erledigungen fertig ist, befindet er sich auf dem Weg zum Zeppelinturm inmitten Orgrimmars! Was auch immer Ihr tut, {name}, Ihr dürft ihn nicht an Bord des Zeppelins und davonkommen lassen!\n\nBeeilt Euch, geht zum Zeppelinturm, bevor Ihr ihn verpasst!", sourceObjective = "Begebt Euch zum Zeppelinturm auf dem zentralen Hügel in Orgrimmar und befragt Flenni Rostrakete zu den Vorräten. Kehrt mit den erhaltenen Informationen zurück.", progress = "Habt Ihr den Kerl gefunden oder hat er sich irgendwo verkrochen?", completion = "Habt Ihr sein Geschäftsbuch bekommen? Wirklich? Das ist wunderbar, {name}! Darin befinden sich bestimmt eine Menge nützlicher Informationen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24577] = { id = 24577, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überprüfung der Ödnisfeste", description = "Euch haben wir es zu verdanken, dass die unmittelbare Bedrohung vorüber ist. Aber meine Arbeit hier im Brachland ist nur der Anfang.\n\nEhrenwacht wurde erobert und Taurajo geplündert, während Kriegsherr Gar'dul noch das Sagen in der Region hatte. Der Kriegshäuptling hat mich geschickt, um das Chaos hier zu beseitigen.\n\nIch möchte, dass Ihr als meine Vorhut zur Ödnisfeste im Süden reitet und Gar'dul wissen lasst, dass es Zeit für eine Abrechnung ist.\n\nSprecht mich an, wenn Ihr bereit seid, aufzubrechen und ich werde meinen Vortrupp zusammentrommeln, damit er Euch begleitet.", sourceObjective = "Sprecht mit Kriegsfürst Blutheft, dann reitet zur Ödnisfeste und informiert Gar'dul, dass Kriegsfürst Blutheft unterwegs zu ihm ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24578] = { id = 24578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schwarzforst", description = "Es hat ein wenig gedauert, aber ich glaube, ich habe endlich herausgefunden, was hier passiert ist. Zumindest teilweise.\n\nIn dieser Stadt gab es einige Überlebende der Seuche. Sie haben sich alle den anderen in den Bergen angeschlossen, an der Witterfront.\n\nAlle sind geflohen, bis auf den Mann, der dieses Tagebuch geführt hat, der alte Bradshaw. Er bemerkte, dass die Angriffe der Worgen plötzlich aufgehört hatten, und entschloss sich, in den Schwarzforst zu reisen.\n\nDirekt nordwestlich der Stadt gibt es eine verlassene Mühle. Dort lebte Bradshaw früher. Schaut Euch da nach Hinweisen um.", sourceObjective = "Untersucht die Bradshawmühle direkt außerhalb von Sturmsiel.", completion = "Ich habe Euch erwartet, {name}. Habt keine Angst.\n\nMein Name ist Belysra. Ich bin eine Priesterin des Mondes… eine Nachtelfe.\n\nIhr kennt Meinesgleichen vielleicht nicht, aber seit der Fluch Euch befiel sind die Schicksale unserer Völker miteinander verbunden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24579] = { id = 24579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sartharion muss sterben!", description = "Sartharion, der Onyxwächter, hütet die Eier des Zwielichtdrachenschwarms. Er hält sich im Obsidiansanktum in der Kammer der Aspekte unterhalb des Wyrmruhtempels auf.\n\nDer Rat der Sechs hat verfügt, dass Sartharion sterben muss!", sourceObjective = "Tötet Sartharion.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Jetzt, wo Sartharion tot ist, werden Todesschwinges und Sinestras Pläne bestimmt ins Stocken geraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24580] = { id = 24580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anub'Rekhan muss sterben!", description = "Anub'Rekhan, einst mächtiger Spinnenfürst im Nerubischen Reich, ist in die Fänge des Lichkönigs geraten, der ihn zu einem Untoten machte.\n\nJetzt fristet er sein Dasein als Gruftlord in seinem Domizil im Arachnidenviertel von Naxxramas und ersinnt Strategien für Kel'Thuzad.\n\nDer Rat der Sechs hat verfügt, dass Anub'Rekhan sterben muss!", sourceObjective = "Tötet Anub'Rhekan.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Der Bericht über Euren Erfolg eilt Euch voraus, {class}. Anub'Rekhan ist Geschichte. Ihr habt ihm einen großen Dienst erwiesen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24581] = { id = 24581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Noth der Seuchenfürst muss sterben!", description = "Noth der Seuchenfürst, Verräter und Feigling! In der Anzahl gegeißelter Seelen folgt er gleich hinter dem Lichkönig selbst.\n\nBegebt Euch schleunigst nach Naxxramas. Dort hält er sich im Seuchenviertel hinter seiner untoten Dienerschaft versteckt.\n\nVernichtet ihn! Der Rat der Sechs hat verfügt, dass Noth sterben muss!", sourceObjective = "Tötet Noth den Seuchenfürst.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Eine Sorge weniger... Jetzt, wo Noth tot ist, wird auch die Forschung der Geißel nach verbesserten Methoden zur Erschaffung Untoter ein Ende haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24582] = { id = 24582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Instrukteur Razuvious muss sterben!", description = "Instrukteur Razuvious stolziert selbstgefällig durch das Militärviertel von Naxxramas. Man sagt, nur ein von ihm persönlich ausgebildeter Todesritter könne der Macht seiner Klinge standhalten.\n\nIhr und Eure Gruppe sollt das Gegenteil beweisen.\n\nDer Rat der Sechs hat verfügt, dass Razuvious sterben muss!", sourceObjective = "Tötet Instrukteur Razuvious.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Gut gemacht, {class}! Razuvious' Untergang hatte eine Verwirrung des Militärbefehls der Geißel aus Naxxramas zur Folge.", sourceObjectiveStatus = "unverified-source-field" }
quests[24583] = { id = 24583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flickwerk muss sterben!", description = "Der sogenannte \"Abgesandte des Krieges\", Flickwerk, ist die ultimative Monstrosität. Außerdem setzt er unseren Truppen in der Drachenöde schwer zu.\n\nIch möchte, dass Ihr Eure Gefährten versammelt und Euch in das Konstruktviertel von Naxxramas begebt, wo Ihr dieses Konstrukt auseinandernehmen sollt.\n\nDer Rat der Sechs hat verfügt, dass Flickwerk sterben muss!", sourceObjective = "Tötet Flickwerk.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", progress = "Meine Quellen berichten, dass Flickwerk noch immer am Leben ist. Gibt es ein Problem, {class}?", completion = "Kinder überall auf der Welt werden besser schlafen können, jetzt, da Flickwerk nicht mehr lebt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24584] = { id = 24584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Malygos muss sterben!", description = "Unsere Ressourcen sind erschöpft. Malygos, der Spruchwirker, entzieht der Welt ihre Magie, um sie im Auge der Ewigkeit zu sammeln. Ohne Magie sind wir verloren!\n\n{class}, der Nexuskrieg muss beendet werden. Der Rat der Sechs hat verfügt, dass Malygos sterben muss!", sourceObjective = "Tötet Malygos.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Nach dem Sieg über Malygos sollte der Nexuskrieg bald beendet sein. Die Dankbarkeit der Kirin Tor ist Euch gewiss, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24585] = { id = 24585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Flammenleviathan muss sterben!", description = "Auf dem Gestaltungsgelände bildet der Flammenleviathan die erste Verteidigungslinie von Ulduar.\n\nDie Kirin Tor haben die Information erhalten, dass diese vom Bewahrer hergestellte Maschine schon bald an einen unbekannten Ort gebracht und auf die Sterblichen von Azeroth losgelassen werden soll, um Verwüstung über sie zu bringen.\n\nDas dürfen wir nicht zulassen. Der Rat der Sechs hat verfügt, dass der Flammenleviathan sterben muss!", sourceObjective = "Tötet den Flammenleviathan.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Ich bin doch immer wieder erstaunt, welche Schrecken man mit dem Gebrauch von Technik erschaffen kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[24586] = { id = 24586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Klingenschuppe muss sterben!", description = "Klingenschuppe bleibt für gewöhnlich in ihrem Horst unweit der Kolossalen Schmiede in Ulduar. Doch in letzter Zeit wurde sie gesehen, wie sie Feuer auf das Land außerhalb des Titankomplexes niederregnen ließ.\n\nZwar hat die Brutmutter eine traurige Vergangenheit, doch stellt sie eine unmittelbare Gefahr für ganz Nordend dar. Der Rat der Sechs hat verfügt, dass Klingenschuppe sterben muss!", sourceObjective = "Tötet Klingenschuppe.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Jetzt kann Veranus endlich in Frieden ruhen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24587] = { id = 24587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ignis, Meister des Eisenwerks, muss sterben!", description = "Der große Feuerriese Ignis, Meister des Eisenwerks, schuftet unermüdlich in der Kolossalen Schmiede von Ulduar. Auf Geheiß von Loken stellt Ignis Waffen von schrecklicher Macht her.\n\nDer Rat der Sechs hat verfügt, dass Ignis sterben muss!", sourceObjective = "Tötet Ignis, Meister des Eisenwerks.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Ich gehe davon aus, dass Ihr nicht mit allzu vielen seiner Eisenkonstrukte konfrontiert wart?", sourceObjectiveStatus = "unverified-source-field" }
quests[24588] = { id = 24588, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "XT-002 Dekonstruktor muss sterben!", description = "Der XT-002 Dekonstruktor, ein weiteres, seltsames Konstrukt von Mimiron, denkt doch tatsächlich, er wäre der Sohn des Bewahrers! Lasst Euch von seiner geheuchelten Unschuld nicht in die Irre führen, er ist eine todbringende Maschine!\n\nIhr findet den Dekonstruktor auf dem Schrottplatz von Ulduar. Der Rat der Sechs hat verfügt, dass der XT-002 Dekonstruktor sterben muss!", sourceObjective = "Tötet den XT-002 Dekonstruktor.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Die größte Schwäche Ulduars ist das blinde Vertrauen ihrer Meister auf die Erfindungen, die sie zum Schutze dort ließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24589] = { id = 24589, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Jaraxxus muss sterben!", description = "Erzmagier Timear hat eine schreckliche Begebenheit vorhergesagt, die sich in Kürze ereignen wird. Ein törichter Gnomenhexenmeister wird während der Prüfung des Kreuzfahrers versehentlich einen Eredarlord der Brennenden Legion heraufbeschwören.\n\nIhr müsst dort sein, wenn es passiert, {class}. Wenn Lord Jaraxxus entkommt, wird er ein Portal öffnen, durch das die Brennende Legion wieder Einzug in unsere Welt erhält.\n\nDer Rat der Sechs hat verfügt, dass Lord Jaraxxus sterben muss!", sourceObjective = "Tötet Lord Jaraxxus.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Ganz Azeroth hatte Glück, dass Timear die Ankunft des Eredarlords vorhergesehen hat und Ihr rechtzeitig dort wart, um ihn zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24590] = { id = 24590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lord Mark'gar muss sterben!", description = "Lord Mark'gar bewacht den Frostthron in der Bastionskammer. Seit der Lichkönig ihn aus den Knochen Tausender bezwungener Abenteurer zusammengesetzt hat, besitzt Mark'gar selbst die Macht des Thrones.\n\nWenn dieses Knochengespenst nicht vernichtet wird, besteht keine Hoffnung, die Eiskronenzitadelle einzunehmen.\n\nDer Rat der Sechs hat verfügt, dass Lord Mark'gar sterben muss!", sourceObjective = "Tötet Lord Mark'gar.\n\nDiese Quest kann von einem Schlachtzug jeglicher Schwierigkeitsstufe oder Größe abgeschlossen werden.", completion = "Dank Euch hat der Frostthron keinen Hauptwächter mehr. Unsere Angriffe auf die Truppen des Lichkönigs werden von nun an von noch größerem Erfolg gekrönt sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24591] = { id = 24591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wachablösung", description = "Wenn Blutheft eintrifft, würde ich gern, äh, unter Ausschluss der Öffentlichkeit mit ihm sprechen. Könnt Ihr mich begleiten um sicherzustellen, dass alles im Lot bleibt? Dieser Blutheft ist, äh, er ist... er ist unberechenbar.\n\n<Gar'dul versucht, seine Fassung zurückzugewinnen.>\n\nTrefft mich oben auf dem nördlichen Turm und wir sprechen gemeinsam mit Blutheft.", sourceObjective = "Geht auf die Spitze des nördlichen Turms in Ödnisfeste und helft Kriegsfürst Blutheft dabei, Gar'dul seines Kommandos zu \"entheben\".", sourceObjectiveStatus = "unverified-source-field" }
quests[24592] = { id = 24592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verrat an der Witterfront", description = "Lord Godfrey hat König Graumähne an der Witterfront gefangen genommen!\n\nEr konnte die beiden Fürsten aus dem Osten überzeugen, sich seinem Plan anzuschließen. Der Narr scheint zu denken, dass er eine Vereinbarung mit den Verlassenen treffen kann, wenn er ihnen Graumähne überlässt.\n\nHört genau zu, {name}. Wir müssen diese Angelegenheit mit so wenig Blutvergießen wie möglich klären.\n\nMit diesem Trank könnt Ihr Euch unerkannt hineinschleichen. Ermordet die verräterischen Fürsten, bevor die Dinge vollkommen außer Kontrolle geraten!", sourceObjective = "Trinkt Krennans Tarnungstrank an der Witterfront und tötet Baron Ashbury und Lord Walden.", progress = "Seid vorsichtig, {name}.", completion = "Ich wünschte, wir hätten es anders lösen können, {name}. Lasst uns sichergehen, dass wir die Sache ohne weiteres Blutvergießen beilegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24593] = { id = 24593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weder Mensch noch Tier", description = "Es ist Zeit, {name}. Diese… Alchemie, die die Bestie in Euch zügelt, hält nicht mehr lange an.\n\nDie ersten verfluchten Worgen waren Nachtelfdruiden, genau wie unsere neuen Verbündeten. Sie haben dem Gleichgewicht, das der Rest ihres Volkes ehrt, den Rücken gekehrt und zugelassen, dass die Bestie in ihrem Inneren die Kontrolle über ihren Verstand übernimmt.\n\nDaher ist es nur Recht, dass ihre Brüder und Schwestern uns von diesem Fluch befreien werden. Geht, {class}. Trinkt von den Wassern des Tal'doren und schließt Frieden mit Euch selbst.", sourceObjective = "Trinkt vom Brunnen der Ruhe, dem Brunnen des Gleichgewichts und dem Brunnen des Zorns.", completion = "Also ist es vollbracht, {name}. Ihr gehört jetzt zu uns.", sourceObjectiveStatus = "unverified-source-field" }
quests[24594] = { id = 24594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, einzutreten. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen. Zeigt die Klinge danach Myralion Sonnenfeuer in Quel'Delars Ruh.", sourceObjective = "Taucht Euer besudeltes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wachen des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", progress = "Ihr seid vom Sonnenbrunnen zurückgekehrt?", completion = "Sind meine Augen tatsächlich auf die Waffe Thalorien Dämmersuchers gerichtet? Heute ist ein großer Tag für alle Sonnenhäscher und alle Sin'dorei!", sourceObjectiveStatus = "unverified-source-field" }
quests[24595] = { id = 24595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Ich gebe zu, ich war zuerst skeptisch, ob Ihr Quel'Delar tatsächlich neu geschmiedet habt und ich hätte auch nicht erwartet, dass Thaloriens Geist sich Euch offenbaren würde. Ihr wisst gar nicht, was es mir und meinem Volk bedeutet, dass Quel'Delar zurückerlangt wurde.\n\nWie versprochen erhaltet Ihr nun Zutritt zum Sonnenbrunnen, wo Ihr die Anführer von Silbermond finden werdet. Bringt das Schwert in die Kammer des Sonnenbrunnens und taucht es hinein. Sobald die Klinge wiederhergestellt ist, zeigt sie Caladis Prunkspeer in Quel'Delars Ruh.", sourceObjective = "Taucht Euer besudeltes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24596] = { id = 24596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen und sprecht anschließend mit Myralion Sonnenfeuer in Quel'Delars Ruh. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjective = "Taucht Euer besudeltes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24597] = { id = 24597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den König von Sturmwind", description = "Möchtet Ihr für den König von Sturmwind einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt König Varian Wrynn von Sturmwind einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24598] = { id = 24598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reinigung Quel'Delars", description = "Der Sonnenbrunnen und das Ende von Quel'Delars Exil sind ganz nah, {name}.\n\nDrinnen werdet Ihr Lor'themar Theron, den Regenten von Quel'Thalas, und Großmagister Rommath antreffen. Seid auf der Hut und lasst Euch nicht in deren politische Pläne verwickeln.\n\nKonzentriert Euch stattdessen auf Eure Aufgabe hier. Taucht das neugeschmiedete Quel'Delar in den Sonnenbrunnen, um die Wiederherstellung abzuschließen und sprecht anschließend mit Myralion Sonnenfeuer in Quel'Delars Ruh. Wendet Euch an einen der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjective = "Taucht Euer getempertes Quel'Delar in den Sonnenbrunnen. Sprecht mit einem der Wärter des Sonnenbrunnens, wenn Ihr bereit seid, das Sonnenbrunnenplateau zu betreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24601] = { id = 24601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Alptraumnarbe", description = "Das bestätigt es. Die Überwucherung hier wird nicht nur von der Fülle der Energie verursacht.\n\nVersteht Ihr? Das geht über das, was in den Höhlen des Wehklagens geschehen ist, hinaus. In den Landen, in denen wir uns befinden, muss sich ein Riss in den Alptraum aufgetan haben. Wenn ich daran denke, dass das mein Fehler ist...\n\nIch werde nicht länger an den Wundrändern herumkratzen. Geht nach Westen ins Zentrum der Überwucherung und trefft mich dort. Wir werden dieser Verderbnis auf den Grund gehen und ihr ein Ende setzen!", sourceObjective = "Helft Naralex, die Alptraumnarbe zu schließen.", completion = "Wir haben es geschafft! Die Verbindung des Alptraums zu dieser Welt wurde gekappt. Der Rest des Landes ist vor dem Eindringen sicher und im Laufe der Zeit werden die Anomalien hier auch wieder dem Naturgleichgewicht unterworfen.\n\nIch kann Euch nicht genug danken, {name}. Ihr habt geholfen, die Ordnung hier wiederherzustellen, und mir dadurch die Gelegenheit gegeben, meine törichten Taten wieder gutzumachen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24602] = { id = 24602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zur Ruhe gebettet", description = "Bei unserer überstürzten Flucht haben wir die Ruhestätten unserer Vorfahren gestört, {name}. Eine Todsünde sozusagen.\n\nEs ist Tradition, ein kleines Andenken in der flachen Erde auf dem Grab eines Einwohners von Gilneas zu hinterlassen. Als die Leute panisch aus diesen Tunneln geflohen sind, wurden diese Andenken freigelegt. Das hat die Geister der Verstorbenen erzürnt.\n\nFindet diese Andenken und bringt sie mir. Wir werden dafür sorgen, dass die Toten zu ihrem ewigen Schlaf zurückkehren.", sourceObjective = "Besorgt 5 freigelegte Andenken.", progress = "Ihr seid zurück, {name}.", completion = "Danke, {name}. Hoffen wir, dass es funktioniert.", sourceObjectiveStatus = "unverified-source-field" }
quests[24603] = { id = 24603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es ist nie genug", description = "Für eine Weile dachte ich, mein Hass hätte sich gelegt. Meine Frau wurde zur letzten Ruhe gebettet, ein letztes Blutopfer ihrer Mörder, um ihre gequälte Seele zu beruhigen. Ich dachte, Frieden würde mir gefallen.\n\nIch habe mich geirrt.\n\nIch werde nicht ruhen, bis auch der letzte dreckige, quiekende, mordende Stacheleber tot und zerschmettert daliegt! Ich kann sie aber mit meinen eigenen Händen nicht schnell genug töten. Geht und tötet noch mehr für mich, {race}.", sourceObjective = "Tötet 13 Stacheleber der Klingenmähnen.", completion = "Gut. Nehmt Eure Belohnung; das ist erst der Anfang.", sourceObjectiveStatus = "unverified-source-field" }
quests[24604] = { id = 24604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sorge um Mankrik", description = "Ich möchte Euch um einen Gefallen bitten {class}.\n\nEin Krieger namens Mankrik ist vor nicht allzu langer Zeit auf seiner einsamen Reise durch unser Lager gezogen. Seine Frau wurde von den Stachelebern vor langer Zeit getötet und ihn dürstet immer noch nach Rache. Ich kann seine Augen nicht vergessen... in ihnen brannte ständig unverhohlener Hass.\n\nWir haben nicht lange miteinander gesprochen, aber ich ertrage den Gedanken nicht, dass er da draußen ganz alleine ist. Bitte bringt dies zu Mankrik und sagt ihm, dass es von mir stammt...", sourceObjective = "Bringt Mahkas Geschenk zu Mankrik südlich der Flammensteinspitze.", progress = "<Mankrik knurrt.>\n\nWas ist? Ich bin beschäftigt.", completion = "Mahka hat Euch geschickt?\n\n<Manriks Wut ebbt einen Moment lang ab.>\n\nDas ist eine kleine Aufmunterung. Aber nichts kann mich trösten, solange ich hier noch nicht fertig bin.", sourceObjectiveStatus = "unverified-source-field" }
quests[24606] = { id = 24606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Blut des Brachlands", description = "Dieser hellrote Stein, den ich in den Klauen eines Stachelebers gefunden habe, wurde sorgfältig in die Form eines großen Ebers geschnitzt, aus dessen Rücken Dornenranken sprießen. Seine Oberfläche ist glatt und abgenutzt.\n\nHaben die Stacheleber ihn hergestellt? Wenn Ihr noch andere findet, kann vielleicht einer der Schamanen an der Flammensteinspitze Euch mehr über sie erzählen.", sourceObjective = "Findet 6 Blutsplitterschmuckstücke bei Stachelebern der Klingenmähnen.", progress = "Ja?", completion = "Das sind Blutsplitter! Früher fand man sie überall im Brachland.\n\nMan sagt, dass sie aus dem Blut von Agamaggan geformt wurden, dem großen Halbgott, von dem die Stacheleber abstammen. Ich wusste, dass die Stacheleber viel Wert auf sie legen, aber niemand hätte gedacht, sie würden sich die Zeit nehmen und sich die Mühe machen, so etwas daraus zu schnitzen...\n\nVielleicht gibt es hier noch mehr zu erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24607] = { id = 24607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Nortet im Osten.", sourceObjective = "Trefft Nortet auf dem Ausbildungsgelände der Dunkelspeere.", sourceObjectiveStatus = "unverified-source-field" }
quests[24608] = { id = 24608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Quetschzahn", description = "Ich schere mich nicht länger um Ehre und Ruhm, {class}. Mich interessiert nur, dass die Stacheleber sterben - egal wie und durch wen.\n\nQuetschzahn, der Häuptling dieser dreckigen Klingenmähnen, sitzt im Nordwesten auf einem Hügel in seinem Bau. Beendet sein Leben.\n\nIch gedenke, hierzubleiben und diese Leichen aufeinanderzustapeln, bis dieses Ungeziefer mir nicht mehr quiekend aus dem Kral entgegenspringt...", sourceObjective = "Tötet Quetschzahn.", completion = "Gut. Gut! Sie werden alle sterben! Ihre Häuptlinge, ihre Frauen, ihre Kinder und ihre widerlichen Haustiere!", sourceObjectiveStatus = "unverified-source-field" }
quests[24609] = { id = 24609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für einen Lord von Eisenschmiede", description = "Möchtet Ihr für Muradin Bronzebart einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt Muradin Bronzebart in Eisenschmiede einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24610] = { id = 24610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für die Hohepriesterin von Elune", description = "Möchtet Ihr für die Hohepriesterin von Elune einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, sie wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt Tyrande Wisperwind in Darnassus einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24611] = { id = 24611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den Propheten", description = "Möchtet Ihr für den Propheten der Exodar einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt Prophet Velen in der Exodar einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24612] = { id = 24612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den Kriegshäuptling", description = "Möchtet Ihr für den Kriegshäuptling einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt dem Kriegshäuptling in Orgrimmar einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24613] = { id = 24613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für die Bansheekönigin", description = "Möchtet Ihr für die Bansheekönigin einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, sie wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt Fürstin Sylvanas Windläufer in Unterstadt einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24614] = { id = 24614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den Oberhäuptling", description = "Möchtet Ihr für den Oberhäuptling einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt Baine Bluthuf in Donnerfels einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24615] = { id = 24615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Geschenk für den Lordregenten von Quel'Thalas", description = "Möchtet Ihr für den Lordregenten von Quel'Thalas einen hübschen Glücksbringerarmreif herstellen? Ich bin sicher, er wird sich freuen!\n\nHabt Ihr schon ein Sammelset für hübsche Glücksbringer?", sourceObjective = "Schenkt Lor'themar Theron in Silbermond einen hübschen Glücksbringerarmreif.", progress = "Seid gegrüßt, {class}! Habt Ihr mir etwas mitgebracht?", completion = "Habt vielen Dank für diesen hübschen Glücksbringerarmreif!", sourceObjectiveStatus = "unverified-source-field" }
quests[24616] = { id = 24616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verfolger abschütteln", description = "Ihr müsst so viele Fragen haben, {name}. Und Ihr werdet auch bald Antworten darauf erhalten.\n\nIch weiß, warum Ihr hier seid und wonach Ihr sucht.\n\nIch kann Euch nicht dahin führen, solange der Feind Euch folgt.\n\nEine von Sylvanas Späherinnen ist Euch auf den Fersen. Ihr dürft den Verlassenen auf keinen Fall den Ort zeigen, den Ihr sucht. Nehmt diesen Talisman und geht einfach die Straße direkt nördlich von hier entlang.\n\nLasst zu, dass die Späherin Euch in ihre Falle lockt, und nutzt dann die Macht des Talismans, um Euch zu befreien und einen Gegenangriff zu starten.", sourceObjective = "Verwendet Belysras Talisman, um die dunkle Späherin zu besiegen.", completion = "Gut gemacht, {name}. Die Späherin hatte nicht die geringste Chance gegen Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24617] = { id = 24617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tal'doren, die Heimstatt in der Wildnis", description = "Es gibt andere wie Euch, {name}. Und auch sie waren verwirrt und wussten nicht, wohin.\n\nEs gibt einen Ort, an den Ihr gehört. Tal'doren, die Heimstatt in der Wildnis, war einst das Zuhause eines Druidenordens, der die Form von Wölfen annehmen konnte.\n\nDort findet Ihr die Antworten, die Ihr sucht. Und dort wird Euch jemand helfen können. Ein alter Freund.", sourceObjective = "Sprecht mit Darius Crowley beim Tal'doren im Herzen des Schwarzforsts.", completion = "Es geht Euch gut, {name}! Ich habe schon so lange auf diesen Tag gewartet. Es ist eine wahre Freude, Euch zu sehen, Freund.\n\nIch habe gehört, was Ihr getan habt, und ich bin Euch so dankbar… besonders für Lorna. Sie ist alles, was mir geblieben ist. Ich lasse sie sofort herholen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24618] = { id = 24618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Anspruch auf die Kriegsnarbe erheben", description = "Wir haben die Allianz hier durch unseren Kampf zum Stillstand gebracht, obwohl das Land unter unseren Füßen auseinanderbricht. Im Osten findet Ihr die Kriegsnarbe, eine weite Schneise stark geschwächten Landes. Sie ist kaum mehr als eine Linie im Sand, aber sie muss UNSERE Linie werden.\n\nIm Zentrum der Narbe befindet sich eine Flagge, die anzeigt, wer gerade über sie herrscht. Findet die Flagge.\n\nWenn sie nicht bereits uns gehört, nehmt sie für die Horde ein - das wird den Kampf zu unseren Gunsten beeinflussen. Untersucht die Narbe und tötet jeden, den Ihr darin findet!", sourceObjective = "Geht zu der Kriegsnarbe. Findet die Flagge und tötet 10 Soldaten der Vorhut der Triumphfeste.\n\nDie Flagge einzunehmen wird allen Hordespielern in der Narbe einen Vorteil im Kampf gewähren.", completion = "Ausgezeichnet! Ihr seid die Art {class}, die ich mag, {name}.\n\nMit Eurer Hilfe werden wir diese Eindringlinge zurück ins Meer treiben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24619] = { id = 24619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Graus Anatomie", description = "Ich wollte schon immer mal versuchen, eine Monstrosität herzustellen. Es sieht recht einfach aus, aber Ihr kennt das ja, wie es ist, etwas aus einem Buch zu erlernen. Es gibt nichts Besseres, als etwas selbst zu tun!\n\nZunächst brauche ich dafür Teile. Viele Teile. Und Ihr werdet sie mir besorgen.\n\nIhr müsst nicht wählerisch sein: menschlich, orcisch... Das ist egal. Teile sind Teile.\n\nIhr müsst nur darauf achten, dass die Leichen, die ihr aberntet, aus der Kriegsnarbe stammen, damit ich weiß, dass sie frisch sind.\n\n<Calder drückt Euch eine verrostete, blutbeschmierte Knochensäge in die Hand und lächelt entwaffnend.>", sourceObjective = "Benutzt Calders Knochensäge an Leichen in der Kriegsnarbe und sammelt 15 abgetrennte Gliedmaße ein.", progress = "Habt Ihr meine Teile bekommen? Lasst mal sehen!", completion = "<Calder späht in den Sack mit den Gliedmaßen und leckt sich mit seiner trockenen, schwarzen Zunge über die Lippen.>\n\nAu weia. Ist das aufregend.\n\n Seid Ihr nicht aufgeregt, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24620] = { id = 24620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Herzen sind Herzen", description = "Diese Teile - herrlich! Muskeln und Sehnen und Finger und Zehen... Jetzt habe ich SO einen Hunger.\n\nAber erst kommt die Arbeit. Sobald ich diesen Teilehaufen zusammengenäht habe, benötige ich ein Herz, das stark genug ist, um Schlick durch dieses Rattennest aus Venen zu pumpen. Ich würde ja mein eigenes Herz benutzen, aber das ist eine verschrumpelte Hülle, die wie eine Rübe aussieht.\n\nNein, ich brauche wahre Stärke. Besorgt mir ein Kodoherz von einem dieser riesigen Landbeberbullen südlich der Kriegsnarbe.", sourceObjective = "Tötet einen Landbeberbullen südlich der Kriegsnarbe und besorgt ein gigantisches Kodoherz.", progress = "Habt doch ein Herz, {name}. Alles, was Ihr wirklich braucht, ist ein Herz.", completion = "<Calder packt das riesige Herz mit beiden Händen, drückt es und lauscht, wie die Kammern schlürfen und schmatzen.>\n\n<Die wächserne Maske seines Gesichts teilt sich zu einem breiten, kindlichen Grinsen.>\n\nEs ist so wichtig, dass man seine Arbeit liebt, findet Ihr nicht auch, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[24621] = { id = 24621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clever ist clever", description = "Meine Monstrosität nimmt langsam Gestalt an! Nun muss ich nur noch ihren Schädel mit etwas Sinnvollem ausstopfen.\n\nIch spreche von einem Gehirn, {name}. Und da werde ich dann wählerisch. Die Vermonstrositierung verursacht erheblichen Hirnschaden also sollte man mit jemand anfangen, der intelligent ist.\n\nEiner der Allianzoffiziere sollte reichen. Findet einen der Hauptleute auf der anderen Seite der Kriegsnarbe und versucht, die Ware nicht zu beschädigen, während Ihr ihn tötet.", sourceObjective = "Tötet einen Hauptmann der Triumphfeste auf der gegenüberliegenden Seite der Kriegsnarbe und besorgt ein frisches Hirn.", progress = "Hiiiiiiiirrrrrrrrrrn...", completion = "<Calder hält das Hirn in seiner ausgestreckten Hand und zieht gleichzeitig ein blutverschmiertes Werkzeug aus seinem Gürtel.>\n\nWunderbare Arbeit! Das Geheimnis hier ist, das tückische Nervensystem nicht zu verletzen, während man die höhere Erkenntnisfähigkeit entfernt. Schließlich können wir nicht zulassen, dass unser neuer Freund ein Gewissen bekommt oder sich daran erinnert, dass er zur Allianz gehört ...\n\n<Calder bohrt und schnippelt an dem Hirn herum und entfernt große Stücke.>\n\nUnd... schon sind wir fertig! Wunderbar.", sourceObjectiveStatus = "unverified-source-field" }
quests[24622] = { id = 24622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Des Trolls bester Freund", description = "Wenn Ihr etwas zu tun sucht, wir hätten da noch ein paar Raptoren, die zu den Ställen gebracht werden müssen. Begebt Euch zu der Insel südlich von hier und trefft Euch mit den Pflegern, die werden Euch dann weiterhelfen.\n\nSie würden sich bestimmt auch über ein wenig Hilfe freuen. Ihr müsst die Liebe verbreiten, wisst Ihr?", sourceObjective = "Redet mit Kijara an der Blutkrallenküste.", completion = "Schön, hier draußen mal neue Gesichter zu sehen, Mann. Wir sind doch recht isoliert, seit wir Orgrimmar verlassen haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24623] = { id = 24623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rettet die Kleinen", description = "Ich habe etwas ziemlich Wichtiges, bei dem ich Eure Hilfe brauche, wenn Ihr bereit seid, Mann.\n\nUnsere Jungtiere werden von jemandem auf der Nachbarinsel geraubt. Zuerst dachte ich ja, sie wären uns davongelaufen oder die Natur habe sie sich genommen, aber mittlerweile fehlen mehr als ein Dutzend der kleinen Racker.\n\nBitte begebt Euch nach Zalazanes Sturz im Nordwesten und weist den Jungtieren den Weg zurück. Die armen Kleinen.", sourceObjective = "Verwendet die Blutkrallenpfeife, um 12 verlorene Brutkrallenjungtiere zu retten.", completion = "Ich danke Euch sehr! Sie können wild werden, wenn man sie provoziert, aber meist wissen sie es halt nicht besser.", sourceObjectiveStatus = "unverified-source-field" }
quests[24624] = { id = 24624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnade für die Verirrten", description = "Der Übeltäter, der unsere Raptoren geklaut hat, muss sie mit irgendeiner Art von Magie verderbt haben. Jetz' da sie mit dieser Verderbnis herangewachsen sind, befürchte ich, dass wir kaum was anderes für sie tun können, außer ihnen einen friedlichen Tod zu gewähren. Geht zu Zalazanes Sturz nordwestlich von hier und übernehmt diese Pflicht.\n\nIch hoffe nur, Ihr habt den nötigen Mumm. Ich glaub' nich', dass ich mich dazu überwinden könnte, auch wenn ich weiß, dass es nötig ist.", sourceObjective = "Tötet 8 verderbte Blutkrallenraptoren.", completion = "Danke, {class}.\n\nEs benötigt tapfere und entschlossene Leute wie Euch, um die Dunkelspeere wieder groß zu machen. Ich hoffe, dass noch mehr Leute kommen, die nur halb so entschlossen sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[24625] = { id = 24625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Gemahl der Seehexe", description = "Ich hab unsere verderbten Blutkrallen untersucht und bin dabei der Ursache dieses Problems auf die Spur gekommen. Es ist ein einzelner Naga. Er hat eine rote Kugel über unsere Jungen gehalten und ich sah, wie sie sich... veränderten.\n\nIch bin mir sicher, dass er denkt, sein Diebstahl und seine Zauber seien nicht bemerkt worden. Es sollte Euch also gelingen, ihn zu überraschen. Tötet den Naga und bringt mir diese unseelige Kugel - Ihr werdet ihn im Nordwesten, an Zalazanes Sturz finden.", sourceObjective = "Tötet Naj'tess und erbeutet seine Kugel.", progress = "Die Naga sind schon seit langer, langer Zeit unsere Feinde. Die letzten Begegnungen mit ihnen verliefen nich' gerade gut. Dieses Mal wird das jedoch anders sein. Die Zeiten haben sich geändert und Ihr seid Teil dieser Veränderung.", completion = "Gut gemacht, {name}! Dieser Naga hat uns enorm zurückgeworfen, aber nichts wird uns auf ewig aufhalten.\n\nEs ist gut, dass Ihr bei uns seid, {name}. Ein wildes Herz schlägt ihn Eurer Brust.", sourceObjectiveStatus = "unverified-source-field" }
quests[24626] = { id = 24626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jung und bösartig", description = "Ihr seid in Ordnung, {name}.\n\nMoraya hat um neue Raptoren zum Ausbilden gebeten. Wir sollten sie nich' länger warten lassen! Einige meiner anderen Rekruten bringen schon ein paar 'rüber, aber ich habe hier einen besonderen Raptor, den ich Moraya vor einer Weile versprochen habe.\n\nFlinkklaue ist einer der schnellsten und mutigsten Jungraptoren, den ich je gesehen habe, aber er kann ein wenig widerspenstig sein. Ich leih' euch ein Lasso, mit dem Ihr ihn nur irgendwo hier auf der Insel einfangen und ihn in die Ställe auf der Hauptinsel steuern müsst. Ich glaub' aber nich', dass er es Euch einfach machen wird.", sourceObjective = "Fangt Flinkklaue und bringt ihn zu den Ställen in der Nähe der Dunkelspeerfeste.", completion = "Flinkklaue! Kijara hat mir von ihm erzählt und es klang, als wäre er schwerer zu hüten als'n Sack Flöhe. Mir kommt die Herausforderung gerade recht. Es sind die Temperamentvollen, die am Ende die mutigsten und treusten Begleiter in der Not abgeben.\n\nVielen Dank, Schätzchen. Wart mir 'ne große Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24627] = { id = 24627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direkt vor unserer Tür", description = "Die Nachtelfen haben uns in dieser Zeit viel beigebracht, {name}. Sie lehrten uns, wer wir sind und wo wir herkommen.\n\nDank ihnen… dank dieses Orts… sind wir keine wilden Tiere mehr. Wir haben unseren freien Willen zurückgewonnen.\n\nDie Verlassenen haben es nicht nur auf unser Land abgesehen.\n\nSie suchen nach etwas, das uns gehört. Ein Artefakt, mit dem sie den Fluch unkontrollierbar auf die gesamte Menschheit ausbreiten können. Wir dürfen nicht zulassen, dass sie es finden.\n\nSylvanas' Banshees rücken immer näher. Helft meinen Spurenlesern, sie zu beseitigen.", sourceObjective = "Tötet 6 heulende Banshees.", completion = "Ihr seid so gut, wie ich Euch in Erinnerung habe, {name}. Wie schön, dass Ihr wieder da seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[24628] = { id = 24628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitungen", description = "Was Ihr als Fluch kennt begann als Ketzerei unter unseren Brüdern.\n\nIm Angesicht der sicheren Niederlage gegen dämonische Mächte haben die Druiden des Rudels dem Gleichgewicht, dem sie sich verschworen hatten, den Rücken gekehrt und zugelassen, dass das Tier in ihnen die Kontrolle übernimmt.\n\nSie wurden in den Smaragdgrünen Traum verbannt, wo sie unter einem Baum wie diesem in ewigen Schlaf versinken mussten. Doch ihre Seuche hatte sich schon auf andere ausgebreitet.\n\nHeute stellen wir in unserer Zeremonie das Gleichgewicht in Eurem Volk wieder her. Bringt mir das Blatt, das nur in der Nähe des Tal'doren wächst.", sourceObjective = "Bringt 6 Mondblätter zu Vassandra.", progress = "Ihr seid zurückgekehrt, {name}.", completion = "Diese einfachen Blätter wachsen durch Elunes Gnade. Sie werden Eurem Geist helfen zu verstehen, warum wir das Gleichgewicht brauchen, und Eurer Seele für alle Zeit lehren, das Tier in Euch zu beherrschen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24629] = { id = 24629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein perfekter Hauch von Parfüm", description = "Ihr scheint mir voller Tatendrang zu sein, {class}. Was haltet Ihr davon, wenn wir uns zusammen einen Plan ausdenken, aus dem beide Seiten als Gewinner hervorgehen?\n\nDie Manufaktur Krone möchte Muster unserer neuesten Feiertagskollektion an so viele potentielle Kunden wie möglich verteilen. Wenn Ihr uns beim Verteilen der Liebe helft, bekommt Ihr Rabatt auf einige tolle Produkte der Manufaktur Krone.\n\nEure Zeit gegen unser Geld - was sagt Ihr dazu?", sourceObjective = "Besprüht 10 Leute mit dem Parfümzerstäuber der Manufaktur Krone.", progress = "Das Parfüm versprüht sich nicht von selbst, wisst Ihr?\n\nFangt an!", completion = "Großartige Leistung, {name}! Die Leute werden in Scharen kommen, um Parfüms der Manufaktur Krone zu kaufen, jetzt, wo sie ihre Wunder testen konnten.\n\nHier habt Ihr eine Kleinigkeit für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24631] = { id = 24631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flugangst", description = "Die Allianz hat Söldner der Wildhämmer angeheuert, um den Himmel oberhalb der Kriegsnarbe zu kontrollieren. Ich glaube, dieselben Greifenreiter waren an dem Feuerbombardement Taurajos während des Angriffs beteiligt.\n\nIch will, dass unser Himmel gesäubert wird.\n\nDie Wildhammerzwerge fliegen tief genug, dass <ein scharfäugiger/eine scharfäugige:c> {class} wie Ihr sie an den Haken bekommt. Nehmt dies. Zielt auf ihre Greife und holt ihre Reiter herunter. Sobald sie sich auf dem Boden befinden, zeigt keine Gnade.", sourceObjective = "Benutzt Tomusas Haken gegen Kriegsgreife der Triumphfeste, um 5 Söldner der Wildhämmer von ihren Reittieren zu stoßen und sie zu töten.", progress = "Die Wildhämmer sind verbissene Kämpfer, in der Luft und auch am Boden. Wie läuft der Kampf?", completion = "<Tomusa schnaubt, als er seinen Haken wieder in Empfang nimmt.>\n\nRache fühlt sich hohl an. Dennoch, ich konnte sie nicht ungestraft davonkommen lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24632] = { id = 24632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache auf Taurenart", description = "Mein Volk ist nicht von Natur aus rachsüchtig, aber manchmal führt der Durst nach Gerechtigkeit dazu, dass wir im Zorn unsere Waffen aufnehmen.\n\nMein alter Freund, Gann Steinkeil, schäumte vor Zorn, als er von dem Gemetzel in Taurajo erfuhr. Die Stammesältesten waren nicht in der Lage, seine Wut im Zaum zu halten.\n\nJetzt hat er der Horde mehr oder weniger entsagt. Er ist abtrünnig geworden, {name}, und versucht, mit einer kleinen Gruppe gleichgesinnter Partisanen einen Schlag gegen die Allianz zu führen.\n\nWenn Ihr ebenfalls Rache sucht, findet Ihr ihn südöstlich von hier am Fuße des Bael Modan.", sourceObjective = "Sucht Gann Steinkeil bei Speerspitze im Südlichen Brachland.", completion = "<Gann mustert Euch von Kopf bis Fuß.>\n\nWir könnten Eure Hilfe brauchen, {class}. Aber das hier ist kein kleines Scharmützel. Wir kämpfen hier, um einen entscheidenden Schlag zu führen - oder bei dem Versuch zu sterben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24633] = { id = 24633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mahkas Bitte", description = "Ich kann ihn mir nicht aus dem Kopf schlagen, {name}. Manchmal in der Nacht, höre ich sein wütendes, klagendes Heulen, das über die Ebenen schallt. Mir vorzustellen, dass er da draußen ist... alleine ... und solche Schmerzen leidet...\n\nBitte, ich muss Euch um einen Gefallen bitten. Geht zu Mankrik und bittet ihn, zu mir zu kommen.", sourceObjective = "Sprecht mit Mankrik.", progress = "Es tut mir leid, Euch darum zu bitten, aber ich möchte, dass er hierher kommt. Er muss diesen Ort des Todes verlassen...", completion = "Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24634] = { id = 24634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krieg der Geheimdienste", description = "Ich bin davon überzeugt, dass die Allianz Spione benutzt, um das Feld auszuspähen und Informationen weiterzugeben. Sie wussten, dass sie den Schlag gegen Taurajo führen müssen, wenn die Jäger draußen auf den Feldern sind. Und sie begegneten jedem Manöver von Gar'dul, als ob er ein offenes Buch wäre.\n\nNun, {name}, ich lasse mich nicht ausmanövrieren. Nicht hier. Wir werden den Kampf um die Informationen gewinnen.\n\nSogar jetzt höre ich Berichte, dass Agenten der Allianz in den Schatten herumschleichen - insbesondere hier, direkt außerhalb dieser Mauern. Tötet sie und bringt mir etwas Nützliches mit.", sourceObjective = "Tötet einen Agenten des Brachlands und nehmt die Anweisungen des SI:7 an Euch.", progress = "Passt auf Euch auf, {class}. Sie könnten überall sein.", completion = "Ha! Der Narr hat diese Befehle nicht vernichtet.\n\nSchauen wir mal, was wir Interessantes erfahren können...", sourceObjectiveStatus = "unverified-source-field" }
quests[24635] = { id = 24635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein feines Duftwasserwölkchen", description = "Ihr scheint mir Unternehmergeist zu besitzen, {class}. Was haltet Ihr von einem kleinen Geschäft?\n\nDie Manufaktur Krone möchte Muster unserer neuesten Feiertagskollektion an so viele potentielle Kunden wie möglich verteilen. Wenn Ihr uns beim Verteilen der Liebe helft, bekommt Ihr Rabatt auf einige tolle Produkte der Manufaktur Krone.\n\nEure Zeit gegen unser Geld - was sagt Ihr dazu?", sourceObjective = "Besprüht 10 Leute mit dem Duftwasserzerstäuber der Manufaktur Krone.", progress = "Das Duftwasser versprüht sich nicht von allein, wisst Ihr?\n\nSprüht los!", completion = "Gute Arbeit, {name}! Die Leute werden die Duftwasser der Manufaktur Krone zuhauf kaufen, jetzt, wo sie sie getestet haben.\n\nHier habt Ihr eine Kleinigkeit für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24636] = { id = 24636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonbonangriff", description = "Ah, ich sehe, dass Ihr Euch keine Gelegenheit entgehen lasst, {class}. Wir könnten zusammen ein wenig Geld machen.\n\nDie Manufaktur Krone muss Muster unserer neuesten Feiertagskollektion an so viele potentielle Kunden in der Stadt wie möglich verteilen. Wenn Ihr uns beim Verteilen der Liebe helft, dürft Ihr auch ein paar tolle Produkte von Manufaktur Krone haben.\n\nEure Zeit gegen unser Geld - kommen wir ins Geschäft?", sourceObjective = "Bewerft 10 Leute mit Schokoladenproben der Manufaktur Krone.", progress = "Wisst Ihr, die Schokolade fliegt nicht von allein zu den Leuten.\n\nIhr müsst anfangen, zu arbeiten!", completion = "Fantastische Leistung, {name}! Die Leute werden sich die Schokolade der Manufaktur Krone gegenseitig aus den Händen reißen, jetzt, wo sie diese süßen, romantischen Leckereien gekostet haben.\n\nHier habt Ihr eine Kleinigkeit für Eure Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24637] = { id = 24637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schlächter von Taurajo", description = "Dieser Agent hatte Befehle, die Straßen zwischen der Kommandantur der Allianz und der Triumphfeste zu sichern. General Hawthorne ist unterwegs.\n\n<Blutheft zerknüllt die Papiere in seiner Faust.>\n\nDas IST er, {name}! Hawthorne - ich spucke den Namen aus - ist derjenige, der den Angriff auf Taurajo befohlen hat! Jetzt wissen wir wann und wo wir ihn niederstrecken können. Schnell, folgt der Straße nördlich der Kriegsnarbe und trefft Euch mit meinem Auftragsmörder Karthog. ZERSCHMETTERT Hawthorne und hängt seinen Körper neben der Straße auf!", sourceObjective = "Sprecht mit Karthog, dann lockt General Hawthorne heraus und verübt ein Attentat auf ihn.", completion = "<Als er die Neuigkeiten hört, schnaubt Blutheft. Seine Augen glitzern. Er legt seinen Kopf in den Nacken und stößt ein abgehacktes, brüllendes Gelächter aus, das von den geschwärzten Mauern der Ödnisfeste zurückgeworfen wird und durch die Hügel dahinter hallt.>\n\nEs ist also vollbracht! Der Schlächter von Taurajo ist wurde endlich zur Strecke gebracht. In den Straßen niedergestreckt wie ein Hund. Wie passend.\n\nIhr habt wohlgetan, {name}. Ihr habt Angst bei unseren Feinden gesät und bald werden wir die Ernte einbringen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24638] = { id = 24638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: im Westen, vor den Toren Orgrimmars. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Lakaien der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport gleich westlich der Tore Orgrimmars in Durotar zu beschädigen und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24639] = { id = 24639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Dinge schlagen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr auch versteht, wie Ihr die Waffe zu schwingen habt, mit der Ihr da rumfuchtelt.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", sourceObjectiveStatus = "unverified-source-field" }
quests[24640] = { id = 24640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Kriegers", description = "Ich glaube, ich kann Euch etwas Neues zeigen. Es ist eigentlich recht einfach, aber auch effektiv.\n\nWenn Ihr schnell die Distanz zu einem Gegner überbrücken wollt, könnt Ihr mit einem aggressiven Schrei gegen ihn anrennen. Dies erwischt ihn auf dem falschen Fuß und ermöglicht es Euch, ihn mit Folgeangriffen zu traktieren, bevor er seine Deckung hochbekommt.\n\nProbiert es aus. Lasst es mich wissen, wenn Ihr meint, dass Ihr es drauf habt.", sourceObjective = "Sprecht mit Nortet, um 'Sturmangriff' zu erlernen. Übt, indem Ihr 'Sturmangriff' gegen Tikiziele verwendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24641] = { id = 24641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", sourceObjectiveStatus = "unverified-source-field" }
quests[24642] = { id = 24642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24643] = { id = 24643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nich' mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[24645] = { id = 24645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: gleich außerhalb Mühlenberns im Silberwald. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Rohlinge der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport außerhalb Mühlenberns im Silberwald zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24646] = { id = 24646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt zurück, was uns gehört", description = "Seit die Verlassenen in Gilneas einmarschiert sind, haben wir uns bemüht, den Aufbewahrungsort der Sichel von Elune geheim zu halten. Wir haben sie im Schutz der Nacht an einen von vielen sicheren Orten gebracht. Die Dunkelläufer sind ihr gefährlich nahe gekommen, haben sie aber nie gefunden... bis jetzt.\n\nZuletzt wurden sie an der Waldrandhütte westlich von hier gesichtet. Stoßt in dieses Horn, wenn Ihr sie gefunden habt. Tobias und seine Fährtenleser werden Euch zu Hilfe eilen und die Dunkelläufer bekämpfen.\n\nNur dann könnt Ihr Euch in die Hütte schleichen und die Sichel zurückholen. Schnell, {name}. Sylvanas darf sie nicht in die Finger bekommen.", sourceObjective = "Blast an der Waldrandhütte in das Horn von Tal'doren und beschafft Euch das mysteriöse Artefakt aus ihrem Inneren.", progress = "Habt Ihr die Sichel, {name}?", completion = "Ich wusste, dass ich mich auf Euch verlassen kann. Ihr habt Eure Sache gut gemacht, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24647] = { id = 24647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: gleich außerhalb des Hügellandhofs im - Ihr habt es erraten - Vorgebirge des Hügellands. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Gauner der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport außerhalb des Hügellandhofs im Vorgebirge des Hügellands zu zerstören und kehrt zu Snap Schnappbolz in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24648] = { id = 24648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: in der Nähe der Späherwacht gleich außerhalb Theramores in den Düstermarschen. Jetzt seht mich nicht so an, okay? Das ist auch unser Problem. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Gangster der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport außerhalb von Theramore in den Düstermarschen zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24649] = { id = 24649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: östlich vom Nistgipfel im Hinterland. Jetzt seht mich nicht so an, okay? Das ist auch ein Problem der Horde. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Agenten der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich des Nistgipfels im Hinterland zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24650] = { id = 24650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: in Winterquell, gleich östlich der Ewigen Warte. Oh, jetzt wird's persönlich. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Besprenkler der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich der Ewigen Warte in Winterquell zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24651] = { id = 24651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: offenbar gleich östlich von Shattrath, in den Wäldern von Terokkar. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Untergebene der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich von Shattrath in den Wäldern von Terokkar zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24652] = { id = 24652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: wie's scheint in den Trostlosen Wäldern des Kristallsangwalds, nordwestlich des Zwielichtspiegels. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Sprüher der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport in den Trostlosen Wäldern des Kristallsangwalds zu zerstören und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", progress = "Habt Ihr es ihnen gezeigt?", completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24653] = { id = 24653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Agamaggans Widerhall", description = "Ich glaube, die Stacheleber werden von mehr als nur reinem Verlangen angetrieben. Würdet Ihr mir helfen, das genauer zu untersuchen?\n\nIm Westen, verstreut über die Siedlungen und Lager der Stacheleber habe ich Eberschädel bemerkt. Aus der Entfernung glänzen sie, glattpoliert... Sie unterscheiden sich von den Überresten, mit denen ihre Abfallhaufen sonst übersät sind. Ich denke, es könnte sich um Gegenstände der Anbetung handeln.\n\nBringt mir einige davon, damit ich sie untersuchen kann, {name}.", sourceObjective = "Findet 3 polierte Eberschädel.", progress = "Habt Ihr die Schädel?", completion = "Ja, das sind ganz klar Symbole für Agamaggan. Aber wenn die Stacheleber immer noch ihrem toten Gott treu ergeben sind, was ist dann die Quelle für ihre bösartige Aggression? Man sagt, Agamaggan war edel und hat sogar sein Leben im Kampf für die Brennende Legion gegeben...\n\nEinen Moment, {name}. Wir müssen uns mit unseren Geistern beraten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24654] = { id = 24654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silithprobleme", description = "Die Silithid! Das sind Käfer, {name}. Oder so etwas Ähnliches wie Käfer. Sie sind widernatürlich...und wir haben eine Burg auf einer Art Ameisenhügel erbaut.\n\nNehmt dieses brennende Pech. Es wird die Nervensägen entzünden und gleichzeitig ihre Erdhöhlen verstopfen. Seid vorsichtig, wenn Ihr das Zeug hier ausgießt - die Silithid werden in Schwärmen herauskommen!\n\nHaltet Ausschau nach Silithid-Buckeln außen um die Ödnisfeste herum. Sie sehen wie Sandhügel aus. Tötet alles, was daraus hervorkrabbelt.", sourceObjective = "Benutzt den Eimer mit brennendem Pech auf Silithid-Buckeln und tötet 10 Silithidschwärmer, wenn sie herauskommen.", progress = "Die Allianz ist nichts. Schwärme von diesen Kribbelkrabblern?\n\n<Crawgol schaudert.>", completion = "Ihr seid mit heißem Teer und Käfersaft bedeckt! Macht Euch keine Sorgen, mein Freund. Das geht wieder ab.\n\nIrgendwann.", sourceObjectiveStatus = "unverified-source-field" }
quests[24655] = { id = 24655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwas stinkt hier", description = "Man sieh sich diese Kerle an. Das Dampfdruckkartell betreibt das Valentinstagsgeschäft schon seit Jahren, und plötzlich tauchen diese Typen auf. Die gehören nicht zum Kartell. Das Kartell hat mich beauftragt, der Sache auf den Grund zu gehen. Irgendwas stinkt hier, und damit meine ich nicht das Parfüm.\n\nNehmt das Gerät, das ich mitgebracht habe, um damit die Parfümwolken zu untersuchen, die die Wachen umgeben. Ich möchte wissen, was sie in das Zeug reintun. Irgendwas ist da faul.", sourceObjective = "Verwendet Schnappbolzens Luftanalysegerät, um die Luft zu untersuchen, die 6 stark parfümierte Wachen umgibt, und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", completion = "Hey, vielen Dank! Gebt her und lasst mal sehen!\n\n<Er nimmt das Gerät an sich und hantiert damit herum.>\n\nOh, das ist gar nicht gut!", sourceObjectiveStatus = "unverified-source-field" }
quests[24656] = { id = 24656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Parfümdiebstahl", description = "Ich wusste, dass die was im Schilde führen! Das Zeug enthält irgendeine bewusstseinsverändernde Chemikalie, doch anhand so einer kleinen Probe kann ich nicht ermitteln, was genau es ist. Ich brauch das echte Zeug.\n\nGeht aber nicht einfach rüber und kauft es. Ich will nicht, dass Ihr den Halunken auch nur ein Kupfer gebt. Nein, wir müssen es von der Quelle besorgen, diskret.\n\nIch werde Euch als Lieferbursche verkleiden. Ich hab einen Vorratshaufen gesehen, der von ihren Schlägern bewacht wurde. Geht und lauft dort vorbei, und bleibt NICHT stehen, sonst halten sie Euch auf! Sie werden Euch eine Kiste zuwerfen, bringt diese hierher.", sourceObjective = "Begebt Euch, während Ihr als Lieferbursche verkleidet seid, zum Vorratslager der Chemiemanufaktur Krone vor den Toren Sturmwinds, kehrt dann mit dem Paket, das sie Euch zuwerfen, zu Inspektor Snip Schnappbolz in Sturmwind zurück.", progress = "Haben sie Euch eine Kiste zum Ausliefern zugeworfen?", completion = "Habt Ihr sie? Gut gemacht! Ganz ausgezeichnet! Mal sehen, was wir hier haben.\n\n<Er öffnet die Kiste und untersucht den Inhalt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24657] = { id = 24657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine nette Unterhaltung...", description = "<Marion hört erschrocken zu, als Ihr ihr erzählt, warum Ihr versucht, Flenni aufzuspüren.>\n\nIhr meint also, er hätte irgendeine Art Chemikalie auf mich angewandt? Igitt! Ich kann nicht glauben, dass ich auf diesen Schwindel hereingefallen bin!\n\nFalls er mit seinen Erledigungen fertig ist, befindet er sich auf dem Weg zum Dock um ein Schiff in die Südlichen Meere zu erwischen! Was auch immer Ihr tut, {name}, Ihr dürft ihn nicht davonkommen lassen!\n\nBeeilt Euch, geht zum Hafen von Sturmwind, bevor Ihr ihn verpasst!", sourceObjective = "Begebt Euch zum Hafen von Sturmwind und befragt Flenni Rostrakete zu den Vorräten. Kehrt mit den erhaltenen Informationen zurück.", progress = "Habt Ihr den Kerl gefunden oder hat er sich irgendwo verkrochen?", completion = "Habt Ihr sein Geschäftsbuch bekommen? Wirklich? Das ist wunderbar, {name}! Darin befinden sich bestimmt eine Menge nützlicher Informationen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24658] = { id = 24658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: nordöstlich der Weststromgarnison im Wald von Elwynn. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Lakaien der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport nordöstlich der Weststromgarnison im Wald von Elwynn zu beschädigen und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24659] = { id = 24659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: gleich südlich des Hains der Uralten in Dunkelküste. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Rohlinge der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport südlich des Hains der Uralten an der Dunkelküste zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24660] = { id = 24660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: gleich südöstlich von Dunkelhain im Dämmerwald. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Gauner der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport auf dem verlassenen Bauernhof südöstlich von Dunkelhain im Dämmerwald zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24661] = { id = 24661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "NEU VERWENDEN", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: im Westen, vor den Toren Orgrimmars. Das kann nicht gut sein. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Lakaien der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport gleich westlich der Tore Orgrimmars in Durotar zu beschädigen und kehrt zu Detektiv Snap Schnappbolz in Orgrimmar zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24662] = { id = 24662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: in der Nähe der Späherwacht gleich außerhalb Theramores in den Düstermarschen. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Gangster der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport außerhalb Theramores in den Düstermarschen zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24663] = { id = 24663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: östlich vom Nistgipfel im Hinterland. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Agenten der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich des Nistgipfels im Hinterland zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24664] = { id = 24664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: in Winterquell, gleich östlich der Ewigen Warte. Oh, jetzt wird's persönlich. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Besprenkler der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich der Ewigen Warte in Winterquell zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24665] = { id = 24665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: offenbar gleich östlich von Shattrath, in den Wäldern von Terokkar. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Untergebene der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport östlich von Shattrath in den Wäldern von Terokkar zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24666] = { id = 24666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Krone zerschmettern", description = "In diesem Geschäftsbuch sind lauter Orte verzeichnet, wo Ihr ein kritisches Auge walten lassen und eingreifen müsst. Es wird Zeit, dass sich etwas ändert!\n\nHier ist ein Eintrag, den Ihr Euch mal ansehen solltet: wie's scheint in den Trostlosen Wäldern des Kristallsangwalds, nordwestlich des Zwielichtspiegels. Begebt Euch dorthin und mischt sie ordentlich auf!\n\nAch ja, und wenn Ihr auf etwas trefft, das groß und gefährlich genug ist, dass es vernichtet werden muss, bewerft es mit dieser Bombe.", sourceObjective = "Tötet 5 Sprüher der Manufaktur Krone, verwendet Schnappbolzens Khoriumbombe, um einen Chemietransport in den Trostlosen Wäldern des Kristallsangwalds zu zerstören und kehrt zu Inspektor Snip Schnappbolz in Sturmwind zurück.", completion = "Gut gemacht! Dafür habt Ihr Euch eine kleine Belohnung verdient. Und kommt doch morgen wieder zu mir, wenn Ihr Zeit habt! Vielleicht habe ich eine Aufgabe für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24667] = { id = 24667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flammensteinspitze", description = "Ich habe diese Silithid-Situation seit fast einem Monat im Griff, was mich zum hiesigen Experten macht. Erst letzte Woche hat uns der Irdene Ring besucht und wollte, dass ich ihnen alles, was ich weiß, aufschreibe.\n\n<Crawgol übergibt Euch ein zerfleddertes Buch.>\n\nIch bin kein guter Schriftsteller. Auch kein Leser, um ehrlich zu sein... Aber dieses Buch ist wahrscheinlich das ausführlichste, das je über diesen Feind geschrieben wurde.\n\nGebt es Tauna Himmelsjäger unten an der Flammensteinspitze. Sie befindet sich südlich von hier, im Westen der Hauptstraße.", sourceObjective = "Liefert Crawgols Silithidenführer bei Tauna Himmelsjäger an der Flammensteinspitze im Südlichen Brachland ab.", progress = "Ah, bringt Ihr mir Nachrichten aus dem Norden?", completion = "Ist das von Crawgol? Wunderbar! Trotz all des Aufruhrs in der Welt können wir unsere Augen nicht vor der Bedrohung durch die Silithiden verschließen. Für den Kampf, der vor uns liegt, ist es unerlässlich, dass Leute wie Crawgol unseren Feind gründlich studieren und seine Geheimnisse aufdecken\n\n<Tauna öffnet das Buch und überfliegt die erste Seite. Ihr Gesicht wird lang.>\n\nOh. Naja. Wenigstens etwas, denke ich.", sourceObjectiveStatus = "unverified-source-field" }
quests[24671] = { id = 24671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Glucken gucken", description = "Lächerlich! Das größte Goblingenie aller Zeiten soll sich um so nichtige Dinge wie Nahrung kümmern?! Für genau diesen Zweck habe ich das Mikromechahuhn erschaffen, und sie lassen es davonlaufen!\n\n<Durch den steigenden Blutdruck wird Hobart noch dunkelgrüner im Gesicht.>\n\nSehe ich etwa aus, als wäre es meine Aufgabe, entflohene Glucken einzusammeln? Nein, mein Freund, nicht mit mir! Mit Bäm vielleicht, aber der ist zu faul.\n\nEuer gesellschaftlicher Rang hat sich in letzter Zeit dramatisch verschlechtert. Ihr macht das!\n\nNehmt dieses ferngesteuerte Feuerwerk und bringt es an den Glucken an. Und zwar schnell!", sourceObjective = "Fangt 10 wilde Glucken, indem Ihr ferngesteuertes Feuerwerk an ihnen anbringt.", completion = "Erfolg! Gab es daran je Zweifel?\n\nGreely, werft schon mal den Geflügelisierer an!", sourceObjectiveStatus = "unverified-source-field" }
quests[24672] = { id = 24672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorwärts und hoch hinaus", description = "Ich werde das tun, worum Darius gebeten hat, und unsere Leute durch den Schwarzforst führen.\n\nIhr solltet zu König Graumähne aufschließen. Er und Krennan sind zur Witterfront aufgebrochen, nachdem Lord Godfrey bestätigt hatte, dass dort ein paar Überlebende ihr Lager aufgeschlagen haben.\n\nFolgt der Straße aus Sturmsiel in die Berge. Ich habe Krennan gebeten, an der Brücke vor der Witterfront auf Euch zu warten.", sourceObjective = "Sucht Krennan Aranas auf der Straße zur Witterfront.", completion = "{name}!\n\nGenn… Sie haben Genn… Sie haben… unseren König verschleppt!", sourceObjectiveStatus = "unverified-source-field" }
quests[24673] = { id = 24673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr nach Sturmsiel", description = "Es wird lange dauern, bis unsere Nation wieder zusammenfindet. Die früheren politischen Streitereien verblassen im Gegensatz dazu, was uns heute entzweit.\n\nDoch wenn es je eine Zeit gegeben hat, da wir uns zusammentun und gegen einen gemeinsamen Feind verbünden müssen, dann jetzt. Und Ihr, {name}, seid es, <der/die> sich als fähig erwiesen hat, diese Lücke zwischen unseren Leuten zu schließen.\n\nKehrt nach Sturmsiel zurück und sagt ihnen, dass der Weg nach Witterfront durch den Schwarzforst sicher ist. Wir kümmern uns um die Verlassenen und folgen ihnen.", sourceObjective = "Sprecht mit Gwen Armstead in Sturmsiel.", completion = "König Graumähne hat mir den Plan kurz erläutert, bevor er in den Schwarzforst aufgebrochen ist. Er klingt trotzdem nicht weniger verrückt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24674] = { id = 24674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Niemandes Sklaven", description = "Ich war einer der wenigen, die entkommen sind, {name}. Nachdem die Verlassenen unser Dorf und unsere Mine eingenommen hatten, haben sie uns mit höchster Grausamkeit behandelt.\n\nDiejenigen von uns, die schwach waren und keine schweren Arbeiten aushielten, ließ dieses abscheuliche Wesen namens Brothogg bis in den Tod schuften.\n\nMeine Frau war eines seiner Opfer, {class}, und ich habe geschworen, dass ich für ihren Tod Rache nehme. Ich bin jetzt zu schwach, aber Ihr könnt für Gerechtigkeit sorgen. Für meine Frau... für Gilneas!", sourceObjective = "Tötet Brothogg den Sklavenmeister in der Glutsteinmine.", completion = "Ich danke Euch, {name}. Unser Volk wird nicht länger unter dem Joch dieser Ausgeburt leiden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24675] = { id = 24675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die letzte Mahlzeit", description = "Ich bin nicht dumm, {name}. Ich weiß, was uns erwartet.\n\nUnser Volk wird diese Tore durchschreiten und gegen einen Feind kämpfen, der besser ausgebildet ist, zahlreicher ist und bessere Waffen als wir hat.\n\nSelbst wenn wir Erfolg haben, werden wir bitter dafür bezahlen müssen. Für die meisten von uns wird das Essen heute Abend die letzte Mahlzeit sein.\n\nIch kann nicht kämpfen, aber ich weiß, wie man kocht. Bringt mir Fleisch von den Hirschen in der Gegend. Ich werde sicherstellen, dass dieses letzte Mahl das Beste wird, was unsere Leute je gegessen haben.", sourceObjective = "Besorgt 10 Stück Hirschfleisch.", progress = "Habt Ihr bekommen, was ich brauche, {name}?", completion = "Ich danke Euch, {name}. Unsere Männer und Frauen werden ein wundervolles letztes Mahl genießen, bevor sie in die Schlacht aufbrechen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24676] = { id = 24676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vertreibt sie!", description = "Unsere Leute sind frei, aber die Stadt wird immer noch von den Verlassenen belagert. Sie sind von ihren Kerntruppen abgeschnitten. Wenn wir sie also vertreiben wollen, ist jetzt die beste Gelegenheit.\n\nIhr Anführer, Exekutor Cornell, ist für seine grenzenlose Rücksichtslosigkeit bekannt. Unter seinen Männern befindet sich auch Valnov der Verrückte, ein so genannter Wissenschaftler, der grausame Experimente an Dorfbewohnern durchführt, die zu alt sind, um in den Minen zu arbeiten.\n\nVernichtet sie alle.", sourceObjective = "Tötet 4 Infanteristen der Verlassenen, Exekutor Cornell und Valnov den Verrückten in Glutstein.", completion = "Jetzt haben wir dank Euch die Bewohner von Glutstein auf unserer Seite.", sourceObjectiveStatus = "unverified-source-field" }
quests[24677] = { id = 24677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flankiert die Verlassenen", description = "Ich danke Euch, {name}. Wir können uns jedoch nicht auf unseren Lorbeeren ausruhen.\n\nWir haben von einem Bergbaudorf erfahren, das derzeit von den Verlassenen besetzt wird. Einige unserer Männer sind zusammen mit Crowleys Tochter zu den nahegelegenen Pferdeställen aufgebrochen, um von dort aus das Kommando zu übernehmen. Liam sollte in Kürze zu ihnen stoßen.\n\nIch bleibe hier und organisiere die letzte Angriffswelle in Gilneas. Sprecht mit Lord Hewell, um Euch ein Pferd zu besorgen, das Euch dorthin bringen kann.", sourceObjective = "Sprecht mit Lord Hewell, um Euch ein Pferd zur Pferdewechselstation zu organisieren, und meldet Euch bei Lorna Crowley.", completion = "Ich bin froh, dass Ihr hier seid, {name}. Wir sind von allen Seiten von den Verlassenen umzingelt und können jede Hilfe brauchen, die wir kriegen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[24678] = { id = 24678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knietief", description = "Es ist Zeit, zusammenzupacken, {name}. Die meisten unserer Leute haben es auf die andere Seite geschafft. Jetzt seid Ihr dran.\n\nNehmt diese Fackel, Ihr werdet sie noch brauchen. Im Tunnel wimmelt es nur so von widerlichen Kreaturen der übelsten Sorte, die Euch in die Knie beißen werden. Verwendet die Fackel, um sie Euch fern zu halten.\n\nSprecht auf der anderen Seite mit Krennan.", sourceObjective = "Nehmt die halb abgebrannte Fackel, um an die andere Seite des Tunnels unter Gilneas zu gelangen.\n\nBereitgestellter Gegenstand:", completion = "Ihr seid hier, {name}. Die meisten haben es auf die andere Seite geschafft, aber jetzt sitzen wir hier, umringt von unseren eigenen… Toten!", sourceObjectiveStatus = "unverified-source-field" }
quests[24679] = { id = 24679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Segen des Patriarchen", description = "Ihr habt es geschafft, {name}. Sogar in Zeiten wie diesen müssen wir unseren Toten die Ehre erweisen.\n\nNehmt diese Opfergaben und legt sie auf Aderics Grab.\n\nHoffen wir, dass sie ausreichen, um die Geister unserer Ahnen zu besänftigen.", sourceObjective = "Legt die gesegneten Opfergaben auf Aderics Grab.", completion = "Es ist vollbracht, {name}. Die Toten versinken wieder in ewigen Schlaf.", sourceObjectiveStatus = "unverified-source-field" }
quests[24680] = { id = 24680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kielwasser", description = "Wir haben vielleicht unsere Stadt verloren, aber zumindest scheinen die Toten uns vergeben zu haben.\n\nSchließt Euch den restlichen Überlebenden in Kielwasser an.\n\nIch bin mir sicher, dass es noch viel zu tun gibt, bevor wir das Gröbste überstanden haben. Genn ist noch nicht eingetroffen, also nehme ich an, dass Lord Crowley dort das Sagen hat.", sourceObjective = "Sprecht mit Lord Darius Crowley in Kielwasser in Gilneas.", completion = "Schön, Euch wiederzusehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24681] = { id = 24681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sie haben Verbündete, aber wir auch", description = "Die Nachtelfen haben ihr Versprechen gehalten. Sie haben uns Schiffe geschickt und bieten uns Schutz in ihrem Land.\n\nLeider sind aber auch die Verbündeten der Verlassenen eingetroffen.\n\nDie Orcs rücken immer näher und das Kanonenboot der Horde schneidet unseren Leuten auf den Transportschiffen den Weg in die Sicherheit ab.\n\nDie Druiden versuchen, den Feind zurückzuhalten, aber lange werden sie nicht durchhalten. Zum Glück haben die Elfenschiffe Belagerungswaffen mitgebracht. Nehmt eine von den Glevenschleudern und tretet dem Feind gegenüber!", sourceObjective = "Benutzt die Glevenschleuder der Nachtelfen, um 40 orcische Räuber, 8 Vorhuten des Wolfschlunds und 4 orcische Kriegsmaschinen zu vernichten.", completion = "Es ist fast vorbei, {name}. Nur noch ein Hindernis steht zwischen uns und unserem Überleben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24682] = { id = 24682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grube von Saron", description = "Schnell, durch das Portal! Ich erwarte Euch auf der anderen Seite.", sourceObjective = "Trefft Fürstin Sylvanas Windläufer am Eingang zur Grube von Saron.", completion = "Unfähige Narren! So langsam frage ich mich, ob sich überhaupt einer von diesen Knilchen vom Turnier als nützlich erweisen wird. Vielleicht könnt Ihr mich ja vom Gegenteil überzeugen...", sourceObjectiveStatus = "unverified-source-field" }
quests[24683] = { id = 24683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grube von Saron", description = "Schnell, durch das Portal! Ich erwarte Euch auf der anderen Seite.", sourceObjective = "Trefft Lady Jaina Prachtmeer in der Grube von Saron.", completion = "Ich habe diesen Geißelfürsten unterschätzt und meine Leute haben dafür bezahlt. Immer, wenn ich denke, dass mich keine größere Schuld mehr an Arthas' Verrat treffen kann, belehrt er mich eines Besseren.\n\nWir müssen weitermachen! Ihr Opfer darf nicht bedeutungslos sein!", sourceObjectiveStatus = "unverified-source-field" }
quests[24684] = { id = 24684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fux im Hühnerstall", description = "<Gann packt Euch mit blutverkrusteter Hand.>\n\nMeine Wunden sind schwerwiegend, aber ich werde nicht aufgeben, bis die Zwerge von Bael Modan für ihre Verbrechen bezahlt haben. <Keuchen> Wir haben während unseres letzten Überfalls einen Mann in ihre Festung hineingeschmuggelt. Einen Saboteur der Goblins: Fux Schattenschleicher. \n\nStartet ein Ablenkungsmanöver vor den Toren, tötet, wen immer Ihr könnt - und dann schleicht Euch in die Festung Bael'dun im Süden und findet Fux.\n\nDiese Festung <hust> kann nur von innen heraus zerstört werden und Fux schafft das nicht alleine.", sourceObjective = "Begebt Euch in die Burg Bael'dun und tötet 10 Zwerge von Bael'dun (Scharfschützen, Soldaten und Offiziere). Dann findet Fux Schattenschleicher, der sich irgendwo dort drinnen versteckt hält.", completion = "Ihr macht gute Arbeit, {class}. Der Aufstand, den Ihr am Eingang zur Burg angezettelt habt, lässt die Zwerge völlig kopflos herumrennen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24685] = { id = 24685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zwergenfestung", description = "Ich weiß nicht, ob Ihr es auf Eurem Weg hinein bemerkt habt, aber die ganze Burg wurde um eine riesige Kanone herum erbaut. Wenn wir nur das Munitionslager finden könnten, dann wären wir in der Lage, hier alles in die Luft zu jagen und es wäre so einfach, wie ein Handkuss!\n\nNur, um das herauszufinden brauche ich die Bauzeichnung der Burg und bisher konnte ich die noch nicht stehlen.\n\nSucht nach den Plänen auf der untersten Etage, direkt die Treppe hier hinunter.", sourceObjective = "Bringt den Plan der Burg Bael'dun an Euch.", progress = "Gebt mir den Plan, schnell! Die Zeit wird knapp.\n\nHauptsächlich, weil ich meine Verkleidung gegessen habe.", completion = "Schauen wir mal, schauen wir mal...\n\nAnscheinend werden die Artilleriegranaten hier vorgefertigt und dann in das gesicherte Lager gebracht...\n\n<Fux reibt sich die Hände.>\n\n{name}, seid Ihr bereit, etwas in die Luft zu jagen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24686] = { id = 24686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fortgespült", description = "Die Blutblüten in Un'Goro durchlaufen einen faszinierenden Lebenszyklus.\n\nDiese Bäume hier vor uns tragen Samen, die hinunter in den Fluss fallen, wenn sie reifen. Die Strömung trägt die Samen dann nach Norden, wo die Saat aufgeht - beinahe wie ein Ei - und eine neugeborene Blutblüte schlüpft.\n\nIch brauche diese Samen für meine Forschung. Nehmt dieses Netz und schöpft damit die leuchtend orangefarbenen Samen aus dem Fluss. Ihr werdet unter Wasser nach ihnen suchen müssen.", sourceObjective = "Verwendet Garls Netz um 4 Blutblütensamen einzufangen.", progress = "Habt Ihr schon alle Samen?", completion = "Hmm... ja, diese Samen dürften ausreichen. Der Zirkel des Cenarius dankt Euch, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24687] = { id = 24687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sträuße des Todes", description = "Die erste Phase des Lebenszyklus der Blutblüten kennt Ihr bereits: die schwimmenden Samen. Die nächste Phase ist aber nicht so zahm: die Rudel Halbwüchsiger.\n\nWenn die Blutblüten geschlüpft sind, bilden sie schnell Banden und ziehen gemeinsam umher, wodurch sie ihre Schwächen mit einer überwältigenden Mehrheit ausgleichen. Diese Banden junger Peitscher bleiben meistens unter sich, aber wenn man auch nur einen einzelnen von ihnen angreift, hat man es schnell mit allen zu tun.\n\nGebietet ihnen im Interesse unserer Sicherheit und der Sicherheit Anderer Einhalt. Ihr findet sie hier in der Nähe, im Westen und Norden.", sourceObjective = "Tötet 6 Rudel halbwüchsiger Blutblüten.", completion = "Ihr kehrt siegreich zurück. Gut, gut... Vielleicht wird der Krater nun etwas sicherer für Reisende sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24688] = { id = 24688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zen'Aliri", description = "Ihr habt bereits einen meiner neuen Schüler kennengelernt, den jungen Worgen namens Garl. Mein anderer Schüler ist der Troll Zen'Aliri. Er hat zur Zeit sein Zelt bei den Entdeckern in Marschalls Expedition westlich von hier.\n\nBringt ihm diese Ergebnisse, {name}, und sagt ihm, er soll sie gründlich lesen.", sourceObjective = "Meldet Euch bei Zen'Aliri in Marschalls Wehr.", sourceObjectiveStatus = "unverified-source-field" }
quests[24689] = { id = 24689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nach Norden fließen", description = "Ithis Mondwärter ist der Nachtelfendruide, der mich in den Zirkel des Cenarius eingeführt hat. Sein Lager liegt nördlich von hier, in der Nähe der Klippen am östlichsten Kraterrand. Folgt dem Strom der Blutblütensamen und ich wette, Ihr werdet ihn dort in der Nähe finden.\n\nMeine Studien beschränken sich lediglich auf die Samen und andere Reagenzien, er jedoch geht viel fortgeschritteneren Dingen nach. Falls Ihr neugierig geworden seid und mehr über die Flora Un'Goros erfahren wollt, solltet Ihr Euch jetzt an ihn wenden.", sourceObjective = "Meldet Euch bei Ithis Mondwärter in den Aufwühlenden Gärten.", completion = "Ahh... Hat Garl Euch geschickt? Wie verlaufen seine Studien? Ich finde, er kann manchmal etwas langsam sein, aber in Bärengestalt sollte man ihn wahrhaftig besser nicht unterschätzen.\n\nNun, es gibt dringendere Dinge, die nach unserer Aufmerksamkeit verlangen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24690] = { id = 24690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sturmflamme", description = "Ich mache mir immernoch etwas Gedanken über diese Feuerelementare, {name}. Eine letzte Bitte: begebt Euch zur Spitze des Feuersäulengrats und tötet denjenigen von ihnen, den sie Sturmflamme nennen. Er ist der größte und stärkste der Feuerelementare im Krater. Ich werde viel besser schlafen, wenn er nur aus dem Weg ist.", sourceObjective = "Tötet Sturmflamme.", completion = "Endlich ist Sturmflamme vernichtet. Danke, {name}... Er hat mich zur Weißglut gebracht.", sourceObjectiveStatus = "unverified-source-field" }
quests[24691] = { id = 24691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eigenartige Delikatessen", description = "He <Süßer/Süße>, Interesse, Euch was dazuzuverdienen?\n\nIch weiß aus sicherer Quelle, dass einige Interessengruppen gutes Geld für Silithidenbeine zahlen. Ja, Ihr habt richtig gehört, Silithidenbeine! Anscheinend sind die richtig lecker, wenn man sie richtig zubereitet. Die sind wie unterirdische Krebse und leben südlich von hier.\n\nDas Problem ist, dass ich eine ordentliche Menge brauche, um meine Ausgaben abzudecken. Meint Ihr, Ihr könntet mir vielleicht so etwa 8 Dutzend beschaffen?", sourceObjective = "Erhaltet 96 Silithidenbeine.", progress = "Ich brauche eine Menge Beine, weil ich doch für den Versand, das Verladen, das Marketing und so weiter bezahlen muss... Oh und Euch muss ich auch noch bezahlen.", completion = "Hervorragend! Wir sitzen hier auf der Spitze von etwas ganz Großem, {name}. Hier ist Euer Anteil an den garantiert riesigen Profiten.\n\nUnd jetzt auf zu anderen Dingen...", sourceObjectiveStatus = "unverified-source-field" }
quests[24692] = { id = 24692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Kolossjunge", description = "Wenn Ihr hier seid, um zu helfen, dann könntet Ihr Euch vielleicht einer lauernden Bedrohung annehmen.\n\nIm Süden liegt die Wuchernde Narbe, ein vor Silithiden wimmelnder Außenposten mitten im Dschungel. Ihr könnt ihn gar nicht übersehen.\n\nEiner meiner Kundschafter berichtet, dass die Silithiden einen jungen Koloss in ihrer großen, unterirdischen Zentralkammer beherbergen. Wenn diese Bestie erst einmal herangewachsen ist, soll sie auf Un'Goro losgelassen werden!\n\nSoweit darf es nicht kommen, {name}. Spürt den Koloss auf und tötet ihn.", sourceObjective = "Tötet das Kolossjunge der Gorishi.", completion = "Ihr habt eine außerordentliche Aufgabe vollbracht, {name}. Diese Belobigung habt Ihr Euch wahrhaftig verdient. Vielen Dank und herzlichen Glückwunsch!", sourceObjectiveStatus = "unverified-source-field" }
quests[24693] = { id = 24693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mooshügel", description = "Hier in Marschalls Wehr kann ich eigentlich nicht so viel Preisschneiderei betreiben, ohne dass die Wissenschaftler misstrauisch werden. Es gibt aber noch einen Ort, an dem Ihr mir von Nutzen sein könntet.\n\nMein Geschäftspartner Gremix hat ein Lager im Nordwesten, auf der anderen Seite des Vulkans. Er ist ein gerissener Geschäftsmann und hat sogar ein noch besseres Gespür für Profit als ich. Ich bin sicher, er könnte für Euch Arbeit finden, wenn Ihr Euch noch ein paar Münzen verdienen wollt.", sourceObjective = "Meldet Euch bei Gremix am Mooshügel.", completion = "Nun gut, wenn Quixxil Euch empfohlen hat, dann müsst Ihr wohl in Ordnung sein. In all den Jahren unserer Zusammenarbeit hat mich Quixxil nie fehlgeleitet.", sourceObjectiveStatus = "unverified-source-field" }
quests[24694] = { id = 24694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Terrasse des Formers", description = "<Als Ihr in die Kugel vor Euch blickt, hört Ihr eine Stimme.>\n\nDie Kristallpylonen wurden aktiviert. Eine ausreichende Menge Kristalle wurde gesammelt. Die Bedingungen wurden erfüllt. Wir sind bereit für den Teleport zur Terrasse des Formers.\n\nSprecht mich an, wenn Ihr bereit seid, {race}. Wir werden uns mit der Wächterin beraten.", sourceObjective = "Sprecht mit dem Prüfer von Un'Goro, um zur Terrasse des Formers teleportiert zu werden, und sprecht dann mit Nablya.", completion = "Ich habe Euch beobachtet, {name}. Eure Ankunft war nicht unerwartet.\n\nIn der Tat ist Eure Ankunft hier schon vor einiger Zeit vorherbestimmt worden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24695] = { id = 24695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der immer wachsame Blick von oben.", description = "Als mein Meister Khaz'goroth die Welt, die Ihr Azeroth nennt, formte, entwarf er den Un'Goro Krater als ein Gebiet, in dem Experimente stattfinden konnten. Man könnte ihn auch die Petrischale der Titanen nennen.\n\nFalls Ihr weiteres Wissen darüber erlangen wollt, wie wir die Welt beobachten, legt die vier Hebel hinter mir um und besteht meine Prüfungen.", sourceObjective = "Legt die Hebel hinter Nablya um und vollendet ihre Prüfungen.", completion = "Ihr habt unter Beweis gestellt, dass Ihr nicht nur weise, sondern auch behände seid, junger {name}. Ich erteile Euch meinen Segen, Euer neuerlangtes Wissen auf Euren Reisen in die Welt zu tragen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24697] = { id = 24697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wie man Fleisch wieder frisch macht", description = "Ich glaube nicht, dass wir einander schon kennengelernt haben... Ich bin Nolen Tacker, der neue Hauptmann der Wache von Marschalls Expedition. Ich bin außerdem der Koch hier. Da gibt es sogar mehr Überschneidungen, als man denken würde.\n\nIch habe eine spaßige kleine Aufgabe für Euch. Habt Ihr die Stachelgruben entlang der Außenbefestigung des Lagers gesehen? Schaut doch mal, ob Ihr nicht einige der Dinosaurier in der Nähe dazu bringen könnt, in diese Fallen zu tappen. Wenn Ihr dieses verfaulende Fleisch nach ihnen werft, wenn sie nicht hinsehen, werden sie entweder hungrig oder böse werden, was beides in Ordnung ist, solange sie Euch nur in die Gruben folgen!", sourceObjective = "Benutzt die Fetzen verdorbenen Fleisches, um die in der Nähe befindlichen Dinosaurier in die Gruben rund um Marschalls Wehr zu locken.", progress = "Werft das Fleisch und lasst Euch dann von den Dinosauriern in die Gruben folgen. So einfach ist das!", completion = "Ausgezeichnete Arbeit, {name}. Jetzt sind wir ein wenig sicherer vor den Dinosaurierüberfällen... Außerdem habe ich all dieses frische Fleisch, das ich meinen Männern servieren kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[24698] = { id = 24698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Archäologische Abenteuer", description = "He, wollt Ihr meine Dimetrodonwürstchen probieren? Nein? Raptorrisotto? Pterrordaxtacos?\n\nNa gut. Oh, da fällt mir etwas ein! Ich habe hier in der Nähe einen Freund, der Eure Hilfe brauchen könnte. Sein Name ist Funks Nilminer und er ist der oberste archäologische Offizier in Marschalls Expedition. \n\nEr wurde hinaus zu den Heißen Quellen von Golakka im Westen geschickt. Ihr werdet ihn wahrscheinlich am Westufer der Quellen finden.", sourceObjective = "Meldet Euch bei Funks Nilminer bei den Heißen Quellen von Golakka.", completion = "Der gute alte Nolen. Wie geht's dem so? Hoffentlich besser als mir...", sourceObjectiveStatus = "unverified-source-field" }
quests[24699] = { id = 24699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gormashh der Klebrige", description = "He, ich hab's! Wir haben es mit den falschen Teergeschöpfen versucht.\n\nGremix hat mir einmal von einer übermäßig großen Teerkreatur erzählt, die ihm über den Weg gelaufen ist. Sie haust in der Nähe der Teergruben weit östlich von hier, südlich vom Fungusfels. Ich wette, je größer diese Kreaturen werden, desto klebriger werden sie! Wir machen schon noch Umsatz, {name}! Vergesst den Schaber nicht!", sourceObjective = "Tötet Gormashh und erhaltet den unglaublich klebrigen Teer.", progress = "Ich zähle auf Euch, {name}. Ich habe mich ziemlich tief für diesen \"Teer als Klebstoff\"-Plan verschuldet und es wäre sehr schade, wenn Ihr mit leeren Händen zurückkehren würdet.", completion = "Ja, dieser Teer ist genau richtig...\n\nHe, wartet mal, meine Hände! Ich bekomme sie nicht mehr auseinander...\n\nVielleicht war das doch keine so gute Idee. Oh, Moment mal! Superklebriger Teerentferner! Da lässt sich das richtige Geld machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24700] = { id = 24700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schwer zu pflücken", description = "Die Teergruben von Lakkari nördlich von hier bergen einen geheimen Schatz: seltene Blumen, die am Boden der Gruben wachsen. Man nennt sie Teerblüten und schätzt sie für ihre Schönheit und Widerstandsfähigkeit. Es ist schon eine Weile her, seit ich das letzte Mal Teerblüten gesammelt habe, also sollten mittlerweile einige neue Pflanzen am Boden der Gruben nachgewachsen sein. Würdet Ihr ein paar für mich holen?\n\nÜbrigens, viel Spaß beim Teerschwimmen. Das hat überhaupt nichts mit Schwimmen im Wasser gemeinsam.", sourceObjective = "Erhaltet 4 Teerblüten.", progress = "Habt Ihr schon die Teerblüten gesammelt? Ich sehe sie nirgends...", completion = "Ah, da sind sie ja. Ausgezeichnete Arbeit, Hübscher! Hier habt Ihr etwas Gold. Ihr habt es Euch verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[24701] = { id = 24701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Marschalls Überbleibsel", description = "Ein Großteil beim Profit machen ist Unverschämtheit. Ihr müsst bereit sein, Euren Nutzen aus dem Unglück anderer zu ziehen. Es läuft alles auf eine Frage hinaus: Wie sehr liebt Ihr Geld?\n\nAls Marschall und seine Truppe ihre Zuflucht im Norden verlassen haben, mussten sie eine Menge Vorräte zurücklassen. Das Zeug ist nicht selten, oder gar besonders wertvoll, aber es liegt dort herum, wenn Ihr gewillt seid, es Euch zu nehmen. Sein Lager ist oben zwischen den Klippen im Norden.\n\nOh, und nehmt Euch in Acht vor was auch immer die anderen in die Flucht geschlagen hat.", sourceObjective = "Erhaltet 10 weggeworfene Vorräte.", progress = "Habt Ihr etwas Brauchbares gefunden?", completion = "Das ist zwar ein Haufen Ramsch, aber dafür ist es ein Haufen KOSTENLOSER RAMSCH und das ist das einzige, was für mich zählt.\n\nNaja, weitestgehend kostenlos. Hier ist Euer Anteil. Danke!", sourceObjectiveStatus = "unverified-source-field" }
quests[24702] = { id = 24702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hier ruht Dadanga", description = "Verlässliches Lasttier und treuer Freund.\n\nStarb kurz nach dem Kataklysmus. Er hatte laute Geräusche immer verabscheut.\n\nAnstelle von Blumen legt bitte ein paar Blutblütensprösslinge nieder. Als er noch am Leben war, hatte er nichts lieber.", sourceObjective = "Erhaltet 10 Blutblütensprösslinge.", progress = "Verlässliches Lasttier und treuer Freund.\n\nStarb kurz nach dem Kataklysmus. Er hatte laute Geräusche immer verabscheut.\n\nAnstelle von Blumen legt bitte ein paar Blutblütensprösslinge nieder. Als er noch am Leben war, hatte er nichts lieber.", completion = "<Ihr verspürt beinahe so etwas wie eine Welle der Dankbarkeit als Ihr die Blutblütensprösslinge auf das Grab legt.>", sourceObjectiveStatus = "unverified-source-field" }
quests[24703] = { id = 24703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine wichtige Lektion", description = "Heda, Reisender! Ihr müsst wissen, dass Ihr das Lager des Maximillian von Nordhain betreten habt. Vielleicht habt Ihr schon Geschichten über meine vielen Heldentaten gehört? Ich kann es Euch ansehen, dass dem so ist. Dieser Funke der Erinnerung huscht über Euer Antlitz wie das Spiegelbild der Weißen Dame über den Steinhügelsee.\n\nEs ist offensichtlich, dass Ihr nach Abenteuern sucht. Da Ihr einigermaßen fähig zu sein scheint, und durch und durch wohlwollend, möchte ich Euch anbieten, mein Knappe zu werden.", sourceObjective = "Sprecht mit Maximillian von Nordhain und erfahrt mehr darüber, wie man Knappe wird.", completion = "Ihr erfreut mich, {name}. Von heute an seid Ihr nicht länger ein einfacher Bettler, sondern ein Knappe im Dienste des Maximillian von Nordhain. Macht Euch bereit für unseren ersten Ausflug, mein treuer Knappe, denn gemeinsam wollen wir uns kopfüber ins Abenteuer stürzen!", sourceObjectiveStatus = "unverified-source-field" }
quests[24704] = { id = 24704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die bösen Drachen im Un'Goro Krater", description = "Dieser Krater ist voll von einer bösartigen Brut von Drachen. Habt Ihr sie gesehen? Sie streifen umher und tragen ihre gezackten Rücken und Echsengesichter überall im Krater zur Schau.\n\nLasst Euch nicht von ihnen in die Irre führen, Knappe, denn diese Drachen sind keine Diener der anmutigen Alexstrasza. Sie sind ganz offensichtlich bösartig und benötigen dringend der Zuwendung einer Heldenklinge.\n\nIch habe beschlossen, dass ich nicht weniger als 15 von ihnen erlegen werde. Als mein Knappe müsst Ihr mich begleiten. Sollten wir getrennt werden, könnt Ihr mich hier an den heißen Quellen wiederfinden.", sourceObjective = "Helft Maximillian von Nordhain 15 \"Drachen\" zu töten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24705] = { id = 24705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dorfbewohner sind zum Retten da", description = "Ich habe so das Gefühl, dass wir in diesem Krater mehr als Drachen vorfinden. Mein Paladininstinkt sagt mir, dass Dorfbewohner in der Nähe sind, die unsere Hilfe brauchen. Wenn jemand in Not ist, dürfen wir es nicht ignorieren.\n\nLasst uns sofort aufbrechen, Knappe {name}! Das Volk von Un'Goro braucht uns!", sourceObjective = "Rettet den Schützling am See, den Schützling auf den Klippen und den Schützling im Norden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24706] = { id = 24706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geister der Heißen Quellen von Golakka", description = "Einen Moment der Ernsthaftigkeit, {name}. Wir haben eine wichtige Aufgabe vor uns. Die verräterischen Drachen, die dieses Tal heimsuchen, werden in ihren Missetaten nicht innehalten, bis wir deren widerwärtige Brutmutter zur Strecke gebracht haben. Bevor wir aber auch nur daran denken können, solch eine Tat zu vollbringen, müssen wir das Licht um Beistand bitten.\n\nIch habe das Licht sich in der Nähe manifestieren sehen und zwar in der Form von Geistern, die an den Ufern der Heißen Quellen von Golakka schweben. Kommt, ich muss mit ihnen sprechen und sie um Hilfe bitten.", sourceObjective = "Wartet in der Nähe, während Maximillian von Nordhain mit 2 dampfenden Furien spricht.", sourceObjectiveStatus = "unverified-source-field" }
quests[24707] = { id = 24707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ballade von Maximillian", description = "Der Augenblick auf den wir gewartet haben, ist nun da, Knappe {name}. Un'Goros Brutmutter wird zu meinen Füßen sterben. Der Ernst unserer Aufgabe liegt mir schwer auf dem Gemüt, aber mit der Macht des Lichts auf unserer Seite können wir nicht scheitern.\n\nSeid Ihr zur Abreise bereit?", sourceObjective = "Helft Maximillian von Nordhain die Königin der Teufelssaurier zu töten. Wenn Ihr von Maximillian getrennt werdet, sprecht mit ihm an den Heißen Quellen von Golakka im Un'Goro Krater.", sourceObjectiveStatus = "unverified-source-field" }
quests[24708] = { id = 24708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Fossilienfinder 3000", description = "Eines der Dinge, die ich am Meisten am Graben hasse, ist die Tatsache, dass man die Hälfte der Zeit nur Dreck findet. Deshalb habe ich den Großteil meiner Zeit hier mit Tüfteln statt mit Graben verbracht.\n\nLasst mich Euch zeigen, was ich erfunden habe: Der Fossilienfinder 3000. Ich habe gerade die letzten Handgriffe daran gemacht. Wenn er richtig funktioniert, sollte er die größten Fossilien in der Umgebung finden. Ich weiß, toll, oder?\n\nProbiert es einmal und schaut, ob Ihr nicht ein paar lächerlich große Dinosaurierknochen finden könnt.", sourceObjective = "Erhaltet eine gigantische Dinosaurierklaue", progress = "Habt Ihr etwas gefunden? Hat es funktioniert?", completion = "Was für einen interessanten Oberschenkelknochen Ihr mir da gebracht habt, aber warum ist er so scharf und geschwungen?\n\n...\n\nEinen Moment mal, das ist eine KLAUE? Ein Dinosaurier mit einer Klaue von solchen Ausmaßen wäre... nun ja, ziemlich groß gewesen, soviel ist sicher. Ist das das einzige Fossil, das Ihr dort gefunden habt?", sourceObjectiveStatus = "unverified-source-field" }
quests[24709] = { id = 24709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Geschichte von den zwei Schaufeln", description = "Einen Moment mal, dieser Knochen hat Spitzhackenkerben. Die stammen nicht von Euch, oder? Nein, ich erkenne diese Kerbe... das muss dieser verdammte Zwerg sein! Gah!\n\nErlaubt mir, dies kurz zu erklären. Es gibt noch einen anderen Archäologen südlich von hier, der Durrin Düsterschippe heißt. Er praktiziert eine rücksichtslose \"Nach mir die Sintflut\"-Archäologie, die sogar mich abstößt.\n\nEin unbezahlbares Fossil ruiniert durch schlampiges Graben. Das ist wirklich das Ende der Fahnenstange, Durrin!\n\n{name}, geht und bereitet Düsterschippe und seiner fahrlässigen Ausgrabung ein Ende.", sourceObjective = "Tötet Durrin Düsterschippe und erhaltet Durrins archäologische Erkenntnisse.", progress = "Ist es vollbracht? Habt Ihr seine Aufzeichnungen bergen können?", completion = "Ich wusste es! Durrin HAT hier herumgewühlt. Und er war dabei etwas auszugraben, was sich als der archäologische Fund des Jahrhunderts herausstellen könnte! Nun muss ich nur herausfinden, wo er die Knochen verstaut hat...\n\nDanke, {name}. Ihr wart mir eine große Hilfe.", sourceObjectiveStatus = "unverified-source-field" }
quests[24710] = { id = 24710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung aus der Grube", description = "Wir müssen den Hauptweg nehmen und durch die Höhle, um zu Tyrannus' Anhöhe zu gelangen.\n\nEr wird sich uns stellen müssen, wenn er verhindern will, dass wir in die Zitadelle selber gelangen.\n\nGeht jetzt, {class}. Meine Leute und ich werden Euch bei der Konfrontation mit Tyrannus zur Seite stehen.", sourceObjective = "Tötet Geißelfürst Tyrannus.", completion = "Welch sinnlose Verschwendung! Arthas ist zu weit gegangen! Ich hoffe nur, dass das, was wir in den Hallen der Reflexion vorfinden werden, all das wert ist.\n\nWenn man den Worten dieses abscheulichen Gnoms trauen kann, sollten sich dort Frostgram und damit auch Antworten auf die Frage befinden, wie Arthas zu begegnen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24711] = { id = 24711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostgram", description = "Wir müssen weiter! Wir sind schon so weit gekommen... wir sind unserem Ziel ganz nah.\n\nIch muss Euch kurz verlassen und Elandra zum Luftschiff zurückschicken. Ich weiß nicht genau, wie wir fliehen sollen, wo wir so viele Leute verloren haben und nur noch wenige übrig sind, die unseren Pfad sichern.\n\nMacht weiter, ich erwarte Euch in den Hallen der Reflexion.", sourceObjective = "Trefft Lady Jaina Prachtmeer am Eingang zu den Hallen der Reflexion.", completion = "Die Hallen der Reflexion, endlich!\n\nLasst mich wissen, wenn Ihr bereit seid. Arthas ist zwar nicht hier, aber es wäre naiv, zu glauben, er ließe Frostgram vollkommen unbewacht zurück.", sourceObjectiveStatus = "unverified-source-field" }
quests[24712] = { id = 24712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befreiung aus der Grube", description = "Wir müssen den Hauptweg nehmen und durch die Höhle, um zu Tyrannus' Anhöhe zu gelangen.\n\nDort wird er sich uns stellen müssen, wenn er verhindern will, dass wir in die Zitadelle selber gelangen.\n\nGeht jetzt, {class}. Meine Leute und ich werden Euch bei der Konfrontation mit Tyrannus zur Seite stehen.", sourceObjective = "Tötet Geißelfürst Tyrannus.", completion = "Die Hallen der Reflexion liegen vor uns. Wenn man den Worten dieses abscheulichen Gnoms trauen kann, sollten sich dort Frostgram und damit auch Antworten auf die Frage befinden, wie Arthas zu begegnen ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[24713] = { id = 24713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Frostgram", description = "Macht weiter, wir sind dem Schwert ganz nahe.\n\nIch brauche einen Augenblick, um eine meiner Dunklen Waldläuferinnen zurück zum Luftschiff zu schicken. Jetzt, wo wir keine Unterstützung mehr haben, müssen Vorkehrungen getroffen werden. Wir brauchen jede Hilfe, die wir kriegen können!\n\nGeht, ich erwarte Euch in den Hallen der Reflexion.", sourceObjective = "Trefft Fürstin Sylvanas Windläufer am Eingang zu den Hallen der Reflexion.", completion = "Die Hallen der Reflexion, endlich!\n\nLasst mich wissen, wenn Ihr bereit seid, {class}. Ich werde nicht so naiv sein, zu glauben, dass Arthas sein wertvolles Schwert vollkommen unbewacht zurückgelassen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[24714] = { id = 24714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Chasing A-Me 01", description = "Irgendetwas muss meiner bislang besten Erfindung zugestoßen sein. Ihr habt doch schon mal mechanische Eichhörnchen gesehen, richtig? Tja, um näher an die Affen des Kraters von Un'Goro heranzukommen, habe ich eine mechanische Äffin geschaffen, die sich unbemerkt unter sie mischen kann - ich nenne sie A-Me 01.\n\nSie untersucht schon seit mehreren Monaten die örtliche Fauna am Fungusfels, aber sie hätte längst zurückkehren sollen. Ich befürchte das Schlimmste.\n\nKönnt Ihr mir helfen, sie zu finden?", sourceObjective = "Findet A-Me 01 am Fungusfels.", completion = "A-Me liegt bewegungslos vor Euch. Durch ihre Bauteile scheint kein Strom zu fließen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24715] = { id = 24715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reparatur von A-Me 01", description = "<Die Augen des Gorillaroboters leuchten plötzlich auf und er beginnt zu sprechen.>\n\n\"… Betriebskapazität… weniger als 5%... Ölbehälter… versehentlich beschädigt…\"\n\n\"… Kokosmilch benutzen… Fels… A-Me 01 retten…\"\n\n<A-Me 01 schließt die Augen.>", sourceObjective = "Ihr seid ziemlich sicher, dass A-Me 01 möchte, dass Ihr eine Kokosnuss von Un'Goro besorgt, sie am Felsen in der Nähe aufschlagt und ihr die Kokosmilch mit hoher Viskosität gebt.", progress = "<A-Me 01 ist in den Energiesparmodus gewechselt.>", completion = "Ihr schüttet die Kokosmilch in das, was Ihr für A-Mes Ölbehälter haltet. Ihr hört, wie die Zahnräder sich zu drehen beginnen und die Stellmotoren surrend anspringen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24717] = { id = 24717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Affen von Un'Goro", description = "Hier in Un'Goro gibt es Unmengen von Gorillas, man muss nur wissen, wo man suchen muss!\n\nDoch während sie in Un'Goro ein gewohnter Anblick sind, gibt es im Norden deutlich weniger Affen. In der Ewigen Warte bringt ein Gorillapelz im Vergleich zum Marktwert hier unten den zehnfachen Preis!\n\nIch werde Euch nicht den ganzen Weg nach Winterquell schicken, das wäre unverantwortlich. Aber ich könnte Eure Hilfe bei der Beschaffung der Pelze brauchen.\n\nIm Nordosten, in der Nähe eines Wasserfalls, befindet sich der Fungusfels. Dort halten sich viele Gorillas auf. Vergesst nicht, auch in der Höhle nachzusehen!", sourceObjective = "Bringt Gremix am Mooshügel 2 Gorillapelze von Un'Goro, 2 Stampferpelze von Un'Goro und 2 Donnererpelze von Un'Goro.", progress = "Ich weiß nie, was gerade modern ist, also will ich ein paar verschiedene Farben. Versucht, Pelze von unterschiedlichen Gorillaarten zu sammeln.", completion = "Hui, gleich zwei von jeder Farbe! Ihr macht keine halben Sachen, was, {name}? Meine Kollegen und ich könnten jemanden wie Euch hier gut brauchen. Habt Ihr je daran gedacht, ins Profitgeschäft einzusteigen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24718] = { id = 24718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der mächtige U'cha", description = "Als Ihr Euch umseht, bemerkt Ihr in diesem Teil der Höhle rote Fellfetzen. Von seiner Beschaffenheit her scheint es Gorillafell zu sein.\n\nIhr erinnert Euch an das Gespräch mit Gremix und seid Euch sicher, dass er an einem roten Gorillapelz sehr interessiert wäre, wenn Ihr einen bekommen könntet.", sourceObjective = "Bringt U'chas Pelz zu Gremix am Mooshügel.", progress = "Rotes Fell? Worauf wartet Ihr noch? Geht und schnappt Euch diesen roten Gorilla! Ich zahle Euch das Doppelte!", completion = "Schaut Euch das nur an! Nicht nur die Farbe, sondern auch die immense Größe… Damit könnte man locker einen Tauren ausstaffieren.\n\nBitteschön, {name}. Das habt Ihr Euch verdient. Bleibt in der Nähe. Ich bin mir sicher, dass wir noch andere Aufgaben für Euch haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[24719] = { id = 24719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weiße Klauen", description = "Halt, {race}. Ich könnte ein wenig Hilfe von <einem/einer:c> {class} wie Euch brauchen.\n\nDirekt außerhalb dieses Lagers gibt es Raptoren mit tödlichen Klauen. Ich habe diese Klauen in einem druidischen Ritual benutzt, aber sie scheinen nicht zu funktionieren. Mir ist jedoch aufgefallen, dass die Klauen einiger Raptoren weiß sind, während die anderen meist tödliche schwarze Klauen haben.\n\nDie Erde geht manchmal komische Wege. Vielleicht könntet Ihr mir ein paar dieser weißen Klauen sammeln, damit ich es noch einmal probieren kann?", sourceObjective = "Sammelt 5 weiße Ravasaurusklauen.", progress = "Habt Ihr schon Klauen finden können?", completion = "Mein Mentor sagt, dass man der Natur manchmal etwas nehmen muss, bevor man ihr etwas zurückgeben kann. Diese Raptoren… Ich habe das Gefühl, dass sie für eine gute Sache gestorben sind.\n\nVielen Dank, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24720] = { id = 24720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Machtkristalle", description = "Ich bin sicher, Ihr habt sie bemerkt, {name}. Sie sind überall!\n\nWovon ich rede? Na, von den Kristallen natürlich!\n\nDie Kristalle... Sie liegen überall im Krater herum. Die meisten Leute ignorieren sie, aber ich habe das seltsame Gefühl, als besäßen sie eine gewisse Macht.\n\nAber hört mal, mir gehen langsam die Kristalle aus - meint Ihr, Ihr könntet noch ein paar für mich sammeln?\n\nDie gelben Kristalle findet Ihr im Nordwesten, die roten im... Ach, Ihr werdet es schon herausfinden.", sourceObjective = "Sammelt 7 Machtkristalle von jeder Farbe: rot, blau, gelb und grün.", progress = "Ich weiß, dass ich hier irgendetwas auf der Spur bin, {name}!", completion = "Jetzt werde ich meine Experimente fortsetzen! Danke, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24721] = { id = 24721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ostpylon", description = "Hoch auf den Klippen über mir gibt es einen großen Kristallpylonen. Ich weiß nicht, wer ihn dort aufgestellt hat, noch fällt mir ein Grund ein, warum man ihn an einem so merkwürdigen Ort errichten sollte.\n\nVielleicht könnt Ihr ja mehr herausfinden als ich. Mir persönlich ist es völlig egal, was dieses Ding tut, also braucht Ihr Euch nicht mehr bei mir zu melden. Aber vielleicht interessiert sich einer der Gelehrten in Marschalls Wehr ja für Eure Entdeckungen.", sourceObjective = "Berührt den Ostpylon im Krater von Un'Goro.", completion = "Es war klug von Euch, mir von diesem Pylonen zu erzählen, {name}. Genau damit beschäftigen sich meine Forschungen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24722] = { id = 24722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Nordpylon", description = "Ihr habt uns schon so viele Gefallen getan, {name}… Jetzt lasst Gremix Euch einmal helfen. Die Angriffe auf Marschalls Zuflucht waren zweifelsohne schrecklich. Sie kamen ohne Vorwarnung und haben keine Gefangenen gemacht. Sie können von Glück sagen, dass so viele überlebt haben.\n\nVor ein paar Wochen bin ich auf den Klippen nordöstlich von hier, im Osten von Marschalls Zuflucht, an einem Kristallpylonen vorbeigekommen. Ich glaube, der Pylon und die Angriffe könnten irgendwie zusammenhängen. Könnt Ihr das vielleicht untersuchen? Ich bin mir sicher, dass jemand in Marschalls Wehr Euch dafür sehr dankbar sein wird.", sourceObjective = "Findet den Standort des nördlichen Kristallpylonen im Krater von Un'Goro.", completion = "Und Ihr glaubt, das könnte irgendwie mit den Angriffen auf Marschalls Zuflucht zusammenhängen?", sourceObjectiveStatus = "unverified-source-field" }
quests[24723] = { id = 24723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Westpylon", description = "Durrins Untersuchungen umfassen einen Punkt, der mich total fasziniert: eine mögliche Verbindung zwischen den Titanen und den Dinosauriern. J.D. Collie im Lager spricht immer von den Titanen hier, den Kristallen da… Vielleicht interessiert sie sich ja dafür.\n\nBevor Ihr Euch jedoch bei ihr meldet, solltet Ihr Euch den Kristallpylonen in der Nähe anschauen. Er befindet sich direkt oben auf den Klippen, westlich von hier. Er ist von Kristallen umgeben. Irgendwie hatte ich immer den Eindruck, dass er etwas mit den Titanen zu tun hat.", sourceObjective = "Findet den Standort des westlichen Kristallpylonen im Krater von Un'Goro.", completion = "Ein Pylon im Westen? Und eine Verbindung zwischen den Titanen und Dinosauriern? Das sind aber viele Informationen auf einmal, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24724] = { id = 24724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallflicker" }
quests[24725] = { id = 24725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallsprengladung" }
quests[24726] = { id = 24726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallkraft" }
quests[24727] = { id = 24727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallspitze" }
quests[24728] = { id = 24728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallbarriere" }
quests[24729] = { id = 24729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kristallschwächer" }
quests[24730] = { id = 24730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Knochenklappern", description = "Man sollte meinen, dass ich gern grabe, nur weil ich der Oberbuddler von Marschalls Expeditionen bin. Es könnte schlimmere Dinge in der Welt geben... auch wenn mir gerade keines einfällt.\n\nJedenfalls sollten wir eigentlich in der Terrorflucht - PHANTASTISCHER Name übrigens - nach toten Stegodonten und Dimetrodonten graben. Na ja, es treiben sich von der Sorte auch noch eine Menge lebende Viecher dort herum! Wil und Hol beschäftigen sich immer mit dieser Todesfalle, daher benötigen wir diese Dinosaurierknochen. Obwohl, unter uns gesagt, wenn Ihr mir welche von einem lebenden Exemplar bringt, dann ist das genauso gut.", sourceObjective = "Besorgt 8 Dinosaurierknochen.", progress = "Ihr könnt von mir denken, was Ihr wollt, aber denen ist es doch völlig egal, ob die Knochen, die sie zum Erforschen bekommen, von uralten Stegodonten und Dimetrodonten stammen oder von den Viechern, die uns beinahe zum Frühstück verspeist hätten, als wir gerade unser Lager aufschlugen. Ich bin schon glücklich, wenn wir hier lebend rauskommen...", completion = "Wunderbar, das sollte funktionieren. Und jetzt, wenn Ihr erlaubt...\n\nDANKE, DASS IHR ALL DIESE KNOCHEN FÜR UNS AUSGEGRABEN HABT, OHNE DEN HIER LEBENDEN TIEREN SCHADEN ZUZUFÜGEN!\n\nOb das wirklich so war oder nicht, das will ich gar nicht wissen. Belassen wir es dabei, in Ordnung? Hier - vielleicht hilft Euch das, über die ganze Angelegenheit Euren Mund zu halten. Jedes Mittel ist recht, wenn wir nur lebendig hier rauskommen, sage ich!", sourceObjectiveStatus = "unverified-source-field" }
quests[24731] = { id = 24731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lar'korwis Mahl", description = "Einst, vor sehr langer Zeit, stahl einer meiner Brüder ein Stück Fleisch aus Lar'korwis Jagdbeute. Damals wusste er es nicht, aber Lar'korwi hat ihn vom Wald aus beobachtet. Lar'korwi folgte meinem Bruder tagelang und vernichtete alles, was er berührte. Mein Bruder, von Angst erfüllt, entschloss sich schließlich, aus dem Krater zu fliehen, um Lar'korwi zu entkommen.\n\nLar'korwi tötete ihn, nicht weit von dieser Stelle entfernt.\n\nWenn Ihr Lar'korwi provozieren wollt, sucht nach seiner letzten Jagdbeute und stehlt ihm etwas Fleisch.\n\nBeginnt Eure Suche im Westen.", sourceObjective = "Sucht das Gerippe von Lar'korwis letzter Jagdbeute und stehlt einen Teil eines Dreschadongerippes.", progress = "Hört auf meine Worte, {name}. Wenn Ihr Euch dieser Kreatur wirklich stellen wollt, dann müsst Ihr vorsichtig sein... und klug. Es bedarf viel Kraft und Kenntnis, um Lar'korwi aus der Reserve zu locken und zu besiegen.", completion = "Das dürfte reichen, {name}. Mir scheint, Lar'korwi scheint dieser Tage gut zu speisen. Allerdings stellt sich mir dabei die Frage, wo er in dieser Gegend einen Dreschadon gefunden haben könnte. Merkwürdig.\n\nWie auch immer, ich werde das behalten, bis Ihr für eine Konfrontation mit der Bestie bereit seid. Macht Euch keine Sorgen um meine Sicherheit - ich bin mir gewiss, Ihr habt Lar'korwi wütend genug gemacht, dass er mich in Ruhe lässt, bis er Euer Fleisch gekostet hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[24732] = { id = 24732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lar'korwis Fährte", description = "Ich bin wirklich erstaunt, dass er noch nicht hinter Euch her ist, {name}. Alles läuft jedoch gut, denn ich habe einen letzten Plan, mit dem wir das Monster zu uns locken können.\n\nAls dominantem Männchen steht es Lar'korwi zu, sich mit jedem Weibchen zu paaren, das ihm gefällt - und ihm gefallen viele. Westlich von hier werdet Ihr eine Menge Ravasauruseier finden. Tretet dicht an sie heran, um damit einen Angriff seiner Artgenossen zu provozieren. Die Weibchen produzieren in einer Drüse an ihrem Kopf einen abscheulichen Gestank, der die Männchen wissen lässt, dass sie paarungsbereit sind. Bringt mir zwei dieser Drüsen.", sourceObjective = "Besorgt 2 Pheromondrüsen eines Ravasaurus.", progress = "Seid vorsichtig, {name}. Wenn Ihr Euch einem Gelege mit Eiern nähert, wird das die Mütter garantiert provozieren... selbst wenn Ihr bereits eine dieser Drüsen habt. Die Mütter können genauso tödlich sein wie Lar'korwi selbst, wenn sie kämpfen, um ihre Jungen zu beschützen. Aber wenn Ihr Erfolg habt, haben wir definitiv das Mittel, um Lar'korwi aus seinem Versteck zu locken.", completion = "Ah, sehr schöne Exemplare, {name}. Die zwei Teile, die Ihr gefunden habt, eignen sich perfekt, um Lar'korwi zu ködern. Ich kann es kaum erwarten, den Ausgang des Kampfs zwischen Euch und dem Monster zu sehen. Es ist ein riesiges Ungetüm mit Klauen so scharf wie die edelsten Klingen. Wenn Ihr ihm in die Augen seht, blickt Ihr direkt in das Antlitz des Todes.", sourceObjectiveStatus = "unverified-source-field" }
quests[24733] = { id = 24733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Köder für Lar'korwi", description = "Das hier wird der schwierigste Teil werden, denn der Plan ist etwas kompliziert. Folgt dem Fluss weiter nach Norden und haltet nach einer Flussbiegung Ausschau. Dort habe ich Lar'korwi zuletzt gesehen. Ihr werdet wissen, dass Ihr im richtigen Gebiet seid, wenn Ihr all die Knochen der großen Kreaturen findet, die es dort einst gab. Nehmt das Fleisch, das Ihr Euch besorgt habt, und legt es dort ab. Reibt das Fleisch dann mit dieser Mischung ein.\n\nWenn es mit beiden Lockmitteln zusammen nicht gelingt, Lar'korwi zu Euch zu locken, dann weiß ich auch nicht weiter.", sourceObjective = "Beschwört Lar'korwi mit dem Inhalt von Torwas Beutel und besiegt ihn. Bringt dann Lar'korwis Kopf zu Torwa Pfadfinder in der Nähe des Eingangs zum Krater von Un'Goro.", progress = "Lasst Euch nicht von Furcht überwältigen, {name}. Es gibt keinen größeren Verräter als Furcht... Ihr müsst stark bleiben!", completion = "Gelobt sei die Erdenmutter! Ihr habt es geschafft! Hut ab, {name}. Ihr habt Euch wahrlich als großartiger Jäger bewiesen. Euer Geist ist stark. Eure Tapferkeit unerreicht. Und Eure Kraft ist noch gewachsen. Ich verbeuge mich vor Eurer Fertigkeit.\n\nNur die größten meiner Vorfahren hätten etwas so Unglaubliches bewerkstelligen können. Herzlichen Glückwunsch.", sourceObjectiveStatus = "unverified-source-field" }
quests[24734] = { id = 24734, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren!", description = "Ihr müsst mir helfen, {name}! Mein Freund Ringo ist vor einer Weile aufgebrochen, um den Vulkan nördlich von hier zu erforschen, und er ist schon viel zu lange weg. Ich mache mir große Sorgen um ihn.\n\nMeint Ihr, Ihr könnt ihn suchen? Nehmt doch meine Feldflasche mit - wenn Ihr Ringo tatsächlich findet, dann hat er sie bestimmt nötig!", sourceObjective = "Sucht nach Hinweisen auf Ringo am Feuersäulengrat.", progress = "Ringos Sack liegt auf dem Felsen vor Euch.", completion = "Dies scheinen Ringos Habseligkeiten zu sein. Wenn er sie hier zurückgelassen hat, kann er nicht weit entfernt sein. Vielleicht solltet Ihr nach ihm suchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24735] = { id = 24735, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Etwas Hilfe von guten Freunden", description = "Argh... es ist so heiß...\n\nIch war gerade dabei, die Gegend zu erkunden, als die Hitze plötzlich unerträglich wurde. Ich muss wohl einen Hitzschlag haben.\n\nBitte, bringt mich zu meiner Freundin Spraggel in Marschalls Wehr zurück. Ich glaube, es geht mir noch gut genug, um Euch dorthin zu folgen.\n\nAber ich fühle mich ziemlich schwach. Wenn ich also noch mal in Ohnmacht fallen sollte, dann bespritzt mich einfach mit etwas Wasser aus Spraggels Feldflasche. Das sollte helfen, hoffe ich...", sourceObjective = "Führt Ringo zu Spraggel Frock in Marschalls Wehr.\n\nFalls Ringo schwach werden sollte, gebt ihm eine Ohrfeige. Falls er ohnmächtig werden sollte, verwendet Spraggels Feldflasche, um ihn zu beleben.", completion = "Ringo ist in keiner besonders guten Verfassung, {name}, aber ich bin froh, dass ich ihn in einem Stück zurückhabe.\n\nDanke, dass Ihr ihn gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24736] = { id = 24736, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sappalots Flieger", description = "Ich baue einen Flugapparat!\n\nIch bin hier gestrandet und habe leider absolut überhaupt keinen Orientierungssinn. Ich würde ja einen Greifen oder Windreiter zurück nach Gadgetzan nehmen, aber diese Viecher jagen mir einfach eine höllische Angst ein.\n\nAlso, werdet Ihr mir helfen? Ich muss nur noch die Flügel bauen und ich glaube, dass sich die Membranschuppen der Pterrordax und Dimetrodonten perfekt dafür eignen würden. Ich werde mich zwar garantiert nicht mit denen anlegen, aber Ihr seht ziemlich zäh aus. Wollt Ihr es nicht versuchen?", sourceObjective = "Sammelt 35 Membranschuppen eines Pterrordax'.", progress = "Jedes berühmte Fahrzeug braucht einen Namen. Ich dachte, ich nenne es... Pwned!", completion = "Ja, diese Schuppen sind perfekt. Mit diesen Schuppen kriege ich meinen Flieger bestimmt in die Luft!\n\nDanke!", sourceObjectiveStatus = "unverified-source-field" }
quests[24737] = { id = 24737, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superkleber", description = "Ich bin immer auf der Suche nach neuen Methoden, um schnelles Gold zu verdienen, {name}. Wenn Ihr mir bei meiner neuesten Idee helft, dann gebe ich Euch ein bisschen was vom Gewinn ab. Na, was sagt Ihr dazu?\n\nDas hab ich mir gedacht!\n\nWir werden ein wenig Klebstoff herstellen. Geht zu den Teergruben nördlich von hier und beschafft mir etwas Teer. Aber nicht jeden x-beliebigen Teer, versteht Ihr? Ihr müsst den von den Kreaturen nehmen, die an den Teergruben leben. Und wenn Ihr meinen Teerkratzer an ihren Leichen verwendet, bleiben sogar Eure Patschehändchen schön sauber.", sourceObjective = "Sammelt 8 Proben superklebrigen Teers.", progress = "Und Tara hat es wieder einmal geschafft - dieser Superkleber wird der letzte Schrei!", completion = "Ja, dieser Teer ist schon ganz schön klebrig. Ich meine, er ist klebrig, aber nicht \"Damit mache ich haufenweise Kohle\"-klebrig. Da muss ich wohl weitergrübeln.", sourceObjectiveStatus = "unverified-source-field" }
quests[24740] = { id = 24740, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vulkanische Aktivität", description = "Willkommen. Ich bin Williden Marschall. Ich führe diese Expedition von Entdeckern und Wissenschaftlern zusammen mit meiner Schwester an. Habt Ihr einen Moment Zeit?\n\nIch mag diesen Anblick der Elementare auf diesem Vulkan da ganz und gar nicht, {class}. Wir haben zu viel Ausrüstung und zu viele Notizen... Wenn auch nur einer dieser wahnsinnigen Elementare sich in unser Lager verirrt, könnte er schlimme, schlimme Schäden anrichten.\n\nZeigt ihnen, dass sie sich nicht mit ihren neuen Nachbarn anlegen sollten. Und bringt mir die Asche, die sie zurücklassen... Wenn wir schon dabei sind, können wir uns gleichzeitig ein wenig der Wissenschaft widmen.", sourceObjective = "Sammelt 9 Proben der Asche von Un'Goro von den Feuerelementaren am Vulkan im Krater von Un'Goro.", progress = "Glaubt Ihr, dass der Vulkan in Un'Goro aktiv ist? Ich frage mich, warum er nicht explodiert ist, als der Kataklysmus uns getroffen hat.", completion = "Ich hoffe, das hat ihnen gezeigt, mit wem sie es zu tun haben. Ich nehme die Asche an mich… Irgendwann wird sie uns sicher nützlich sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24741] = { id = 24741, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein guter Tausch", description = "Hobart glaubt also, dass er uns mit diesem kleinen Gluckeneiern abspeisen kann? Pah! Wir besorgen uns richtige Eier!\n\nIch habe bereits ein paar Fallen auf dem Raptorenbuckel den Pfad entlang Richtung Osten aufgestellt. Die stacheligen Raptoren werden sich sofort auf die Gluckeneier stürzen, sodass Ihr sie gegen ihre größeren Eier tauschen könnt.\n\nGenial!", sourceObjective = "Sammelt 5 Eier eines stacheligen Raptors.", progress = "Wie viele habt Ihr zusammen? Ich kann das riesige Omelette fast schon schmecken, das wir daraus kochen werden!", completion = "Super! Schaut nur, wie groß diese Dinger sind!\n\nDie kann Wurfhammer sicher nicht überbieten!", sourceObjectiveStatus = "unverified-source-field" }
quests[24742] = { id = 24742, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Quelle finden", description = "Ich habe ein Thermometer entwickelt, um die Temperaturen am Vulkan zu messen, und ich würde gern die heißeste Stelle finden. Es zeigt die Messungen in Grad Kraklenheit an!\n\nHier, nehmt es und messt die Temperaturen am Grat, wann immer Ihr eine heiße Stelle seht!\n\nHeiße Stellen erkennt Ihr in der Regel an einer leuchtenden Felssäule. Ihr findet sie um den Feuersäulengrat herum. Eine Umrundung sollte eigentlich schon genügen.", sourceObjective = "Krakle im Krater von Un'Goro möchte, dass Ihr den heißesten Bereich des Feuersäulengrats findet.\n\nImmer, wenn Ihr eine heiße Stelle findet, benutzt das Thermometer, um die Temperatur zu überprüfen. Sucht, bis Ihr die heißeste Stelle gefunden habt.", progress = "Ich würde ja selbst gehen, aber... ich habe ein wenig Angst vor den Feuerelementaren dort!", completion = "Diese Ergebnisse sind verblüffend! Mein Chef wird sehr zufrieden sein. Vielen Dank, lieber {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[24743] = { id = 24743, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schattenschneide", sourceObjective = "Hört gut zu, {class}. Indem Ihr diese Waffe annehmt, wird Euer Schicksal besiegelt.\n\nSiegt oder geht unter.\n\nIch habe Euch auf diesen Weg gebracht, womit ich die Verantwortung für Euch übernommen habe. Solltet Ihr ins Wanken geraten, ist es meine Pflicht, Euch von diesem Leben zu erlösen.\n\nDenkt an meine Worte, {race}, und versagt nicht!", sourceObjectiveStatus = "unverified-source-field" }
quests[24744] = { id = 24744, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das größte Ei aller Zeiten", description = "Bäm Megabombe? Was glaubt er eigentlich, wer er ist? Seine Eier von stacheligen Raptoren sind gar nichts gegen das, was wir uns jetzt besorgen werden!\n\nWie Ihr wisst, verfügt die Instastadt für genau solche Nahrungsengpässe über ein Mikromechahuhn. Und zu unserem großen Glück konnte ich mit meinem überragenden Intellekt ermitteln, wohin unser wunderbares vorprogrammiertes Geflügel entschwunden ist.\n\nGeht nach Norden zur Versengten Rinne. Aber Vorsicht! Seine Platinen sind durchgebrannt und ich glaube, es ist gar nicht mehr so mikro!", sourceObjective = "Besorgt Euch das größte Ei aller Zeiten.", progress = "Malt Euch nur die Lobeshymnen aus, die auf mich herniederregnen werden… äh… ich meine uns, wenn wir ihnen das größte Ei aller Zeiten bringen!", completion = "Heureka! Und wieder einmal hat mein Genie den Tag gerettet! Nehmt das, Bäm Megabombe!\n\nUnd jetzt wollen wir den Erfolg ernten!", sourceObjectiveStatus = "unverified-source-field" }
quests[24745] = { id = 24745, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendwas liegt in der Luft (und Liebe ist es nicht)", description = "Auf die Innenseite der Karte sind verrückte, detaillierte Pläne gekritzelt, einen Großteil Azeroths zu infizieren. Das müsst Ihr sofort einem der Ermittler des Dampfdruckkartells zeigen!", sourceObjective = "Bringt die vergilbte schöne Grußkarte zu Inspektor Snip Schnappbolz in Sturmwind.", progress = "Habt Ihr Euch um diese nichtsnutzigen, Ränke schmiedenden Gauner gekümmert?", completion = "Was habt Ihr denn da?\n\nUi, das ist groß! Riesig! So viele verrückte Details auf einem Haufen! Danke, Ihr habt uns wirklich sehr geholfen. Mit Euch kann man wirklich gut zusammenarbeiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24746] = { id = 24746, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[24747] = { id = 24747, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sabotage!", description = "Diese zwergischen Artilleriegranaten haben einen eingebauten Luftdetonationszeitzünder. Das ist ja einfach! Ihr müsst nur eine der Artilleriegranaten in der Ladebucht sabotieren und sie dann hinauf ins Lager befördern. Bumm, Baby. BUMM!!\n\nIhr findet die Granaten in einer der beiden Ladebuchten hinter der Hauptwerkstatt auf dieser Ebene. Sie befindet sich direkt um die Ecke.\n\nSobald Ihr die Artilleriegranate manipuliert habt... Rennt! Rennt wie der Wind, {name}! Dann meldet Euch bei Gann im Lager zurück. Ich bin direkt hinter Euch.", sourceObjective = "Sabotiert eine zwergische Artilleriegranate und flüchtet dann aus Bael'dun bevor es explodiert.", completion = "Bael'dun? Zerstört?\n\n<Gann dreht seinen Kopf, um hinter sich zu spähen, wo dunkle Rauchwolken den Himmel verdunkeln, und zuckt schmerzerfüllt zusammen.>\n\n{name}, mein Freund. Ihr habt Taurajo und das Volk der {race} gerächt. Die Eindringlinge werden sich von dem Schlag nicht so schnell erholen. Danke.", sourceObjectiveStatus = "unverified-source-field" }
quests[24748] = { id = 24748, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das letzte Gefecht des Lichkönigs", description = "Schattengram; eine neu geschmiedete Waffe, die bereits mit der Geschichte dieser Welt getränkt ist, wiedergeboren in eine beispiellose Bestimmung.\n\nMit dieser Waffe tragt Ihr eine feierliche Verantwortung, und die Zeit, dieser Verpflichtung nachzukommen, ist gekommen.\n\nNehmt diese mythische, legendäre Waffe und marschiert gegen den Feind. Rächt die zahllosen Helden, die in diesem gnadenlosen Krieg ihr Leben ließen. Bringt ihren geschundenen Seelen Frieden.\n\nStählt Euch, {class}, und führt Schattengram, um den Sinn ihrer Erschaffung zu erfüllen.", sourceObjective = "Hochlord Darion Mograine in der Eiskronenzitadelle will, dass Ihr den Lichkönig tötet.", completion = "Dann ist es also endlich vollbracht.\n\nMögen die Völker Azeroths unserer Taten hier ewig gedenken. Mögen die Opfer so vieler für immer in ihren Herzen brennen. Mögen sie im Angesicht großer Bedrohungen nie die Bereitschaft verlieren, ihr Leben für andere zu riskieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24749] = { id = 24749, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfüllt mit unheiliger Macht", description = "Bevor Eure Waffe ihre volle Kraft entfalten kann, muss sie mit den für sie charakteristischen Kräften ausgestattet werden. Die erste davon ist Unheiligkeit.\n\nIhr müsst jemanden namens Professor Seuchenmord ausfindig machen und töten, doch das ist noch nicht alles. Ihr müsst seine eigenen Mittel und Methoden gegen ihn verwenden.\n\nFindet einen Weg, seinen mutierten Schleim zu absorbieren. Benutzt die stinkende Substanz, um Eure Waffe mit unheiliger Macht zu erfüllen. Erst dann sollt Ihr Eure nächste Aufgabe von mir erhalten.", sourceObjective = "Hochlord Darion Mograine möchte, dass Ihr Schattenschneide mit unheiliger Macht erfüllt und Professor Seuchenmord tötet.\n\nDiese Quest kann nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle abgeschlossen werden.", completion = "Gut gemacht, {class}!\n\nWir kommen dem Abschluss unserer Arbeit immer näher.", sourceObjectiveStatus = "unverified-source-field" }
quests[24750] = { id = 24750, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Soratha im Osten.", sourceObjective = "Trefft Soratha auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nDoch aus Eurem Blick spricht Entschlossenheit. Feurige Augen. Ihr habt alle Voraussetzungen für einen echten {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24751] = { id = 24751, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Ziele treffen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr die Grundlagen der arkanen Künste beherrscht.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Zaubern... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24752] = { id = 24752, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Magiers", description = "Ich glaube, ich kann Euch etwas Neues zeigen. Es ist eigentlich recht einfach, aber auch effektiv.\n\nWenn Eure arkanen Energien in perfektem Einklang sind, könnt Ihr eine Salve arkaner Geschosse abfeuern, die Euren Gegnern großen Schaden zufügen wird. Es mag etwas Zeit und eine Portion Glück erfordern, diese Kunst zu erlernen, also seid geduldig.\n\nProbiert es aus. Lasst es mich wissen, wenn Ihr meint, dass Ihr es drauf habt.", sourceObjective = "Redet mit Soratha, um 'Arkane Geschosse' zu erlernen. Wendet den Zauber zweimal bei einem Tikiziel an.", completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24753] = { id = 24753, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[24754] = { id = 24754, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24755] = { id = 24755, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24756] = { id = 24756, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfüllt mit der Macht des Blutes", description = "Nun kann Eure Waffe mit der Macht des Blutes versehen werden.\n\nIhr müsst gegen Blutkönigin Lana'thel kämpfen und Euch ihrem Blutspiegel aussetzen. Durch diese Macht wird Schattenschneide das Blut des nächstgelegenen Lebewesens trinken. Das wäret dann Ihr, {race}.\n\nLasst, sobald die Klinge erwacht ist, den rasenden Blutdurst der Königin über Euch kommen, gebt Euch ihm hin und bereitet ihr einen schmachvollen Tod.\n\nMögen ihre Schreie in den Ohren des Lichkönigs schmerzen, während er auf sein Schicksal wartet!", sourceObjective = "Hochlord Darion Mograine möchte, dass Ihr Schattenschneide mit der Macht des Blutes erfüllt und Blutkönigin Lana'thel besiegt.\n\nDiese Quest kann nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle abgeschlossen werden.", completion = "Gut gemacht, {class}.\n\nSchattengram ist fast in Reichweite.", sourceObjectiveStatus = "unverified-source-field" }
quests[24757] = { id = 24757, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Erfüllt mit der Macht des Frostes", description = "Nun ist Schattenschneide bereit, mit der letzten Macht erfüllt werden.\n\nSindragosa, das persönliche Reittier des Feindes, muss fallen! Doch bevor Ihr sie tötet, müsst Ihr ihrer Frostatemattacke viermal widerstehen ohne zu sterben.\n\nIst der Drache erst einmal beseitigt, steht nichts mehr zwischen Euch und dem Lichkönig.", sourceObjective = "Hochlord Darion Mograine hat Euch den Auftrag erteilt, Sindragosa zu töten, nachdem Ihr 4-mal ihren Atemattacken ausgesetzt wart, während Ihr Schattenschneide führt.\n\nDiese Quest kann nur im Schwierigkeitsgrad für 25 Mann der Eiskronenzitadelle abgeschlossen werden.", completion = "Die Axt hat die Mächte aufgesogen, {race}, und die Schmiede ist bald bereit für die Erschaffung von Schattengram...", sourceObjectiveStatus = "unverified-source-field" }
quests[24758] = { id = 24758, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Nekali im Osten.", sourceObjective = "Trefft Nekali auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nDoch aus Eurem Blick spricht Erfahrung. Weise Augen. Ihr habt alle Voraussetzungen für eine echte {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24759] = { id = 24759, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Dinge schlagen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr die Grundlagen der natürlichen Künste beherrscht.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Zaubern... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24760] = { id = 24760, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Schamanen", description = "Ich glaube, ich kann Euch etwas Neues zeigen. Es ist eigentlich recht einfach, aber auch effektiv.\n\nWenn Ihr die Macht der Elemente in Eure Waffe leitet, könnt Ihr einen schnellen, brutalen Angriff auf Eure Feinde ausführen.\n\nProbiert es aus. Lasst es mich wissen, wenn Ihr meint, dass Ihr es drauf habt.", sourceObjective = "Redet mich Nekali, um 'urtümlicher Schlag' zu lernen. Wendet den Zauber dreimal bei einem Tikiziel an.", completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24761] = { id = 24761, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Mädel. Die geben sicher 'n paar mächtige Mäntel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[24762] = { id = 24762, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24763] = { id = 24763, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24764] = { id = 24764, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Zen'Tabra im Osten.", sourceObjective = "Trefft Zen'Tabra auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nDoch aus Eurem Blick spricht Wildheit. Scharfe Augen. Ihr habt alle Voraussetzungen für einen echten {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24765] = { id = 24765, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Dinge schlagen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr die Grundlagen der druidischen Künste beherrscht.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Zaubern... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24766] = { id = 24766, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Druiden", description = "Ich glaube, ich kann Euch etwas Neues zeigen. Es ist eigentlich recht einfach, aber auch effektiv.\n\nIndem Ihr die Kräfte der Natur ruft, könnt Ihr Knochen und Schnitte heilen. So könnt Ihr selbst die schwerst verwundeten Verbündeten weiterkämpfen lassen.\n\nProbiert es aus. Lasst es mich wissen, wenn Ihr meint, dass Ihr es drauf habt.", sourceObjective = "Redet mit Zen'tabra, um 'Verjüngung' zu erlernen. Übt den Zauber an einer verwundeten Wache der Dunkelspeere beim Übungsgelände der Dunkelspeere.", completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24767] = { id = 24767, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[24768] = { id = 24768, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24769] = { id = 24769, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24770] = { id = 24770, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Legati im Osten.", sourceObjective = "Trefft Legati auf dem Ausbildungsgelände der Dunkelspeere.", completion = "Noch so ein Jungblut, wie?\n\nDoch aus Eurem Blick spricht Gerissenheit. Scharfe Augen. Ihr habt alle Voraussetzungen für einen echten {class}.\n\nLasst uns keine Zeit mehr verschwenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24771] = { id = 24771, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Ziele treffen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr auch versteht, wie Ihr die Waffen zu schwingen habt, mit denen Ihr da rumfuchtelt.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", completion = "Nicht schlecht, Mann. Es liegt eine natürliche Grazie in Euren Schwüngen... Ihr habt womöglich Talent.\n\nEin paar Ecken und Kanten sind natürlich noch zu glätten, aber ich werde Euch noch einiges beibringen in nächster Zeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[24772] = { id = 24772, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Schurken", description = "Ich glaube, ich kann Euch etwas Neues zeigen. Es ist eigentlich recht einfach, aber auch effektiv.\n\nWährend Ihr Eure Gegner bekämpft, könnt Ihr Ihre Schwächen aufdecken und vernichtende Komboangriffe ausführen. Nachdem Ihr ein paar Schläge zur Schwächung Eurer Gegner ausgeführt habt, erledigt sie mit einem brutalen 'Ausweiden'-Angriff.\n\nProbiert es aus. Lasst es mich wissen, wenn Ihr meint, dass Ihr es drauf habt.", sourceObjective = "Redet mit Legati, um 'Ausweiden' zu erlernen. Wendet es dann 3 Mal bei einem Tikiziel an.", completion = "Gute Arbeit, Mann! Das schien Euch ja wirklich leicht zu fallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24773] = { id = 24773, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", progress = "Sie sind sicher keine große Herausforderung, Mann, aber sie können einem ganz schön die Knöchel zerkratzen, wenn man nicht schnell genug auf den Beinen ist.", completion = "Das sind nette Pelzchen, Junge. Die geben sicher 'n paar mächtige Mäntel ab.", sourceObjectiveStatus = "unverified-source-field" }
quests[24774] = { id = 24774, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", completion = "Ihr seid sehr gut in Form. Eines Tages werdet Ihr sehr mächtig sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[24775] = { id = 24775, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", completion = "Ihr seid der neue Rekrut, von dem alle reden, hm? Willkommen bei den Dunkelspeeren.", sourceObjectiveStatus = "unverified-source-field" }
quests[24776] = { id = 24776, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Ortezza im Osten.", sourceObjective = "Trefft Ortezza auf dem Ausbildungsgelände der Dunkelspeere.", sourceObjectiveStatus = "unverified-source-field" }
quests[24777] = { id = 24777, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Dinge schlagen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr auch versteht, wie Ihr die Waffe zu schwingen habt, mit der Ihr da rumfuchtelt.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", sourceObjectiveStatus = "unverified-source-field" }
quests[24778] = { id = 24778, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kunst des Jägers", description = "Ich glaube, ich kann Euch etwas Neues zeigen. Es ist eigentlich recht einfach, aber auch effektiv.\n\nEs gibt alle möglichen Spezialschüsse, die mit Bögen oder Gewehren verwendet werden können, aber wenn Ihr dabei keine ruhige Hand habt, werdet Ihr schnell erschöpfen und keinen wirklichen Schaden anrichten. Nehmt Euch Zeit, richtet Euren Bogen aus und lasst die Pfeile auf Eure Gegner herabregnen.\n\nProbiert es aus. Lasst es mich wissen, wenn Ihr meint, dass Ihr es drauf habt.", sourceObjective = "Redet mit Ortezza, um 'zuverlässiger Schuss' zu erlernen. Wendet ihn 5 Mal bei einem Tikiziel an.", sourceObjectiveStatus = "unverified-source-field" }
quests[24779] = { id = 24779, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", sourceObjectiveStatus = "unverified-source-field" }
quests[24780] = { id = 24780, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grube der Bewährung", description = "Ihr habt Euch ganz schön gemausert, {class}. Ich bin sicher, ich könnte Euch hier und da einen Trick oder zwei beibringen, aber ich werde Eure Zeit nicht mehr mit Tikizielen verschwenden.\n\nIch habe also eine letzte Prüfung für Euch, Mann. Geht rüber zur Grube in der Mitte von diesem Gebiet und kämpft gegen einen echten Fiesling - einen, der Euch auch umbringen will. Lasst es den Gefängniswärter wissen, wenn Ihr bereit seid.", sourceObjective = "Redet mit einem Gefängnisaufseher der Dunkelspeere, betretet dann die Grube der Bewährung und besiegt einen gefangenen Späher der Gallschuppen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24781] = { id = 24781, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr als erwartet", description = "Ihr bringt auf jeden Fall mehr als erwartet, Mann. Ich bin sicher, es gibt noch mehr wichtige Sachen, bei denen wir Eure Fähigkeiten gebrauchen können. Ihr müsst nicht mehr mit dem Nachwuchs herumhängen.\n\nGeht zum Dorf im Südosten und stellt Euch vor. Helft hier und da und ich bin sicher, dass Ihr schnell aufsteigen und mehr Ansehen erlangen werdet.", sourceObjective = "Meldet Euch bei Vol'jin in der Dunkelspeerfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[24782] = { id = 24782, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufstieg der Dunkelspeere", description = "Die Trolle des Dunkelspeerstamms waren lange Zeit Opfer. Ausgestoßene. Immer wieder mussten wir fliehen und unser Zuhause verlassen. Aber diesmal hat uns nicht die Flucht hierher getrieben.\n\nVol'jin bot uns Führung durch Weisheit, und das hat uns so lange am Leben erhalten. Nun bietet uns diese Weisheit Vorzeichen einer chaotischen Zukunft für die Horde und für Garrosh Höllschrei.\n\nNein, diesmal fliehen wir nicht. Diesmal kämpfen wir für ein Zuhause, das bestehen bleibt.\n\nEs ist Zeit, mit Eurer Ausbildung zu beginnen, {name}. Sprecht mit Tunari im Osten.", sourceObjective = "Trefft Tunari auf dem Ausbildungsgelände der Dunkelspeere.", sourceObjectiveStatus = "unverified-source-field" }
quests[24783] = { id = 24783, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Grundlagen: Ziele treffen", description = "Alles klar, Mann. Fangen wir mit den Grundlagen an. Ich muss wissen, dass Ihr die Grundlagen der heiligen Künste versteht.\n\nGeht und zerstört diese Tikiziele. Geht es langsam an. Natürlich. Ich beobachte Eure Form und dann sehen wir weiter.", sourceObjective = "Zerstört 6 Tikiziele.", sourceObjectiveStatus = "unverified-source-field" }
quests[24784] = { id = 24784, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Künste eines Priesters", description = "Ich glaube, ich kann Euch etwas Neues zeigen. Es ist eigentlich recht einfach, aber auch effektiv.\n\nIndem Ihr heilige Energien sammelt, könnt Ihr Eure Wunden oder die Eurer Verbündeten verbinden. Diese Magie ist schnell, aber sie entzieht Euch auch Energie. Mit fortschreitender Übung werdet Ihr Varianten erlernen, die Euch nicht ganz so viel Energie entziehen.\n\nProbiert es aus. Lasst es mich wissen, wenn Ihr meint, dass Ihr es drauf habt.", sourceObjective = "Redet mit Tunari, um 'Blitzheilung' zu erlernen. Wendet diese bei 5 verwundeten Wachen der Dunkelspeere beim Übungsgelände der Dunkelspeere an.", sourceObjectiveStatus = "unverified-source-field" }
quests[24785] = { id = 24785, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aller Anfang ist schwer", description = "Woll'n wir Eure Fertigkeiten mal nutzen, Mann. Ich fange ganz einfach an.\n\nDa sind Katzen unterwegs, die unsere Eber töten. Wir teilen unser Essen aber nich' gerne. Diese Eber müssen am Leben bleiben, wenn Ihr heute Abend was zu beißen haben wollt.\n\nSie sind überall auf der Insel. Bringt mir ein paar Katzenpelze!", sourceObjective = "Sammelt 6 Felle einer Wildmähnenkatze.", sourceObjectiveStatus = "unverified-source-field" }
