quests[24791] = { id = 24791, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Täglicher, zufälliger, normaler Dungeon (Nter)" }
quests[24792] = { id = 24792, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "V-Mann", description = "Ihr wirkt, als könntet Ihr Euch nun um den Strippenzieher all dessen kümmern. In dem Geschäftsbuch steht, er hätte sich auf Burg Schattenfang verkrochen. Dorthin sollt Ihr Euch begeben.\n\nEiner unserer Leute befindet sich bereits vor Ort, doch er selbst kann nichts unternehmen. Geht jetzt, der Ermittler erwartet Euch. Und nehmt ein paar Freunde mit.", sourceObjective = "Meldet Euch bei Ermittler Fezzen Kupferstapel auf Burg Schattenfang.", completion = "Fantastisch! Hilfe kann ich wirklich gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24793] = { id = 24793, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "V-Mann", description = "Ihr wirkt, als könntet Ihr Euch nun um den Strippenzieher all dessen kümmern. In dem Geschäftsbuch steht, er hätte sich auf Burg Schattenfang verkrochen. Dorthin sollt Ihr Euch begeben.\n\nEiner unserer Leute befindet sich bereits vor Ort, doch er selbst kann nichts unternehmen. Geht jetzt, der Ermittler erwartet Euch. Und nehmt ein paar Freunde mit.", sourceObjective = "Meldet Euch bei Ermittler Fezzen Kupferstapel auf Burg Schattenfang.", completion = "Fantastisch! Hilfe kann ich wirklich gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24794] = { id = 24794, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sprecht mit Spraggel", description = "Meine gute Freundin Spraggel ist schon eine ganze Weile wegen einer gewissen Sache beunruhigt. Ich würde ihr ja helfen, aber wie Ihr seht, habe ich es gerade schön bequem.\n\nKönntet Ihr nicht nachsehen, was sie möchte?", sourceObjective = "Sprecht mit Spraggel Frock in Marschalls Wehr.", completion = "Was? Krakle schickt Euch?", sourceObjectiveStatus = "unverified-source-field" }
quests[24795] = { id = 24795, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sieg für den Silberbund", description = "Trotz der Angeberei Königin Lana'thels habt Ihr Quel'Delar wiederhergestellt, {name}. Wie lange haben wir davon geträumt, Quel'Delar wieder an uns zu nehmen.\n\nNicht nur der Silberbund, sondern alle Quel'dorei schulden Euch ihren Dank.\n\nDas Schwert scheint zu wissen, dass Ihr als {class} nicht über die nötige Ausbildung verfügt, es zu führen, und hat sich daher nicht an Euch gebunden. Wo wird sein nächster Meister dann herkommen? Vielleicht kann der Argentumkreuzzug helfen. Geht nach Norden zum Argentumturnierplatz und übergebt das Schwert im Namen des Silberbunds an Justiziarin Mariel Treuherz.", sourceObjective = "Bringt das wiederhergestellte Quel'Delar zu Justiziarin Mariel Treuherz beim Argentumturnierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[24796] = { id = 24796, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sieg für den Silberbund", description = "Trotz der Angeberei Königin Lana'thels habt Ihr Quel'Delar wiederhergestellt, {name}. Wie lange haben wir davon geträumt, Quel'Delar wieder an uns zu nehmen.\n\nNicht nur der Silberbund, sondern alle Quel'dorei schulden Euch ihren Dank.\n\nVereesa Windläufer, die Anführerin des Silberbunds, hat Euch nach Eurer Rückkehr vom Sunnenbrunnen zu sich gebeten. Nehmt Quel'Delar mit Euch und geht zu Dalarans Violetter Zitadelle, wo sie auf Euch wartet, {name}.", sourceObjective = "Bringt das wiederhergestellte Quel'Delar zu Vereesa Windläufer in der Violetten Zitadelle in Dalaran.", progress = "Ist es wahr, dass Ihr Quel'Delar wiederhergestellt habt?", completion = "Das ist nichts weniger als eine sensationelle Leistung, {name}. Der Tag, an dem Thalorien und Anasterian gefallen sind, derselbe Tag, an dem Quel'Delar verloren ging, war einer der schwärzesten Tage meines Lebens. Quel'Delar jetzt wiederhergestellt zu sehen... ich kann es nicht in Worte fassen.\n\nOhne Zweifel seid Ihr dazu ausersehen, der wahre Träger der Klinge zu sein. Quel'Delars Magie hat bereits damit begonnen, die Klinge an Eure Fähigkeiten und Stärken anzupassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24797] = { id = 24797, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "REUSE" }
quests[24798] = { id = 24798, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sieg für die Sonnenhäscher", description = "Endlich, Quel'Delar ist zum Ruhme der Sonnenhäscher und der Sin'dorei wiederhergestellt!\n\nGanz Silbermond wird Euch als Helden feiern, {name}.\n\nDas Schwert scheint zu wissen, dass Ihr als {class} nicht über die nötige Ausbildung verfügt, es zu führen, und hat sich daher nicht an Euch gebunden. Wo wird sein nächster Meister dann herkommen? Noch hat sich kein würdiger Sin'dorei gemeldet. Lasst uns den Rat des Argentumkreuzzugs suchen. Geht nach Norden zum Argentumturnierplatz und übergebt das Schwert im Namen der Sonnenhäscher an Justiziarin Mariel Treuherz.", sourceObjective = "Bringt das wiederhergestellte Quel'Delar zu Justiziarin Mariel Treuherz beim Argentumturnierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[24799] = { id = 24799, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sieg für die Sonnenhäscher", description = "Endlich, Quel'Delar ist zum Ruhme der Sonnenhäscher wiederhergestellt!\n\nDie gesamte Horde wird Euch als Helden feiern, {name}.\n\nDas Schwert scheint zu wissen, dass Ihr als {class} nicht über die nötige Ausbildung verfügt, es zu führen, und hat sich daher nicht an Euch gebunden. Wo wird sein nächster Meister dann herkommen? Ich kann meine Enttäuschung nicht verbergen... ich hatte gehofft, es würde ein würdiger Sin'dorei sein. Lasst uns den Rat des Argentumkreuzzugs suchen. Geht nach Norden zum Argentumturnierplatz und übergebt das Schwert im Namen der Sonnenhäscher an Justiziarin Mariel Treuherz.", sourceObjective = "Bringt das wiederhergestellte Quel'Delar zu Justiziarin Mariel Treuherz beim Argentumturnierplatz.", sourceObjectiveStatus = "unverified-source-field" }
quests[24800] = { id = 24800, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sieg für die Sonnenhäscher", description = "Endlich, Quel'Delar ist zum Ruhme der Sonnenhäscher und der Sin'dorei wiederhergestellt!\n\nGanz Silbermond wird Euch als Helden feiern, ebenso wie die gesamte Horde, {name}.\n\nDer Erzmagier Aethas Sonnenhäscher, der Anführer der Sonnenhäscher, hat Euch nach Eurer Rückkehr vom Sunnenbrunnen zu sich gebeten. Nehmt Quel'Delar mit Euch und geht zu Dalarans Violetter Zitadelle, {name}. Der Erzmagier will Euch persönlich gratulieren!", sourceObjective = "Bringt das wiederhergestellte Quel'Delar zu Erzmagier Aethas Sonnenhäscher in der Violetten Zitadelle in Dalaran.", progress = "Ist es wahr, dass Ihr Quel'Delar wiederhergestellt habt?", completion = "Quel'Delar erhebt sich von neuem, so wie wir Sin'dorei uns aus der Asche der Niederlage und des Verrats erhoben haben. Das Herz und die Waffe von Thalorien Dämmersucher sind beide mit Euch, {name}.\n\nIch sehe, dass die Klinge bereits begonnen hat, sich an Eure Stärken anzupassen, {name}. Haltet Euer Haupt erhoben und Quel'Delar stets an Eurer Seite.", sourceObjectiveStatus = "unverified-source-field" }
quests[24801] = { id = 24801, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Sieg für die Sonnenhäscher", description = "Endlich, Quel'Delar ist zum Ruhme der Sonnenhäscher und der Horde wiederhergestellt!\n\nDies ist ein wahrer Segen für unsere Bemühungen gegen den Lichkönig.\n\nDer Erzmagier Aethas Sonnenhäscher, der Anführer der Sonnenhäscher, hat Euch nach Eurer Rückkehr vom Sunnenbrunnen zu sich gebeten. Nehmt Quel'Delar mit Euch und geht zu Dalarans Violetter Zitadelle, {name}. Der Erzmagier will Euch persönlich gratulieren!", sourceObjective = "Bringt das wiederhergestellte Quel'Delar zu Erzmagier Aethas Sonnenhäscher in der Violetten Zitadelle in Dalaran.", progress = "Ist es wahr, dass Ihr Quel'Delar wiederhergestellt habt?", completion = "Quel'Delar erhebt sich von neuem, so wie wir Sin'dorei uns aus der Asche der Niederlage und des Verrats erhoben haben. Und dennoch hat sich die Waffe Thalorien Dämmersuchers aus irgendeinem Grunde entschieden, einem Außenseiter zu dienen.\n\nBeruhigt Euch, {name}. Ich gedenke nicht, Eure Errungenschaft zu schmälern, da Ihr etwas vollbracht habt, was keiner meiner Brüder vermocht hat, obschon ich nicht weiß, wie Ihr es angestellt habt. Ihr seid eindeutig dazu ausersehen, sein Träger zu sein... die Klinge hat bereits begonnen, sich an Eure Stärken anzupassen. Tragt Quel'Delar mit Stolz im Kampf gegen unsere Feinde.", sourceObjectiveStatus = "unverified-source-field" }
quests[24802] = { id = 24802, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Zorn des Lichkönigs", description = "Es besteht wohl kaum Hoffnung, Arthas auf den Stufen seines eigenen Thrones zu besiegen. Und wer übernimmt in diesem Fall die Krone des Lichkönigs?\n\nViele Fragen sind noch offen, doch zuerst müsst Ihr Sylvanas finden und vor dem Lichkönig fliehen, so lange Zeit dazu ist.", sourceObjective = "Findet Fürstin Sylvanas Windläufer und flieht aus den Hallen der Reflexion.", completion = "Und wieder schlüpft mir die Rache durch die Finger. Es ist schwer zu glauben, wie viel stärker er geworden ist.\n\nEs war töricht von Euch, wegen mir herzukommen, aber dennoch ist es gut zu wissen, dass es immer noch einige Champions der Horde gibt, die keine nutzlosen Feiglinge sind. Die Informationen, die Uther uns gab, mögen wohl der Schlüssel dafür sein, Arthas endlich zu besiegen, aber es wird immer deutlicher, dass die Horde dies nicht allein wird bewerkstelligen können.\n\nGeht, {class}. Ich gehe davon aus, dass Eure Fähigkeiten bald wieder gebraucht werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24803] = { id = 24803, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angelwettstreit der Kalu'ak", progress = "Wir Kalu'ak habe eine lange Tradition, unsere Angelfertigkeiten weiter zu polieren, indem wir sie jede Woche auf die Probe stellen.\n\nDie erste Person, die einen Schwarzspitzenhai fängt und zu mir bringt, wird fürstlich belohnt werden und fürderhin als größter Angler des Nordens bekannt sein... zumindest für ein paar Tage.\n\nDie Leibspeise des Schwarzspitzenhais ist der Pygmäenschiffshalter. Versucht, die Schwarzspitze überall dort zu angeln, wo Ihr normalerweise den Schiffshalter angeln würdet.", completion = "Steht nicht nur so da rum! Gebt mir den Hai und ich erkläre Euch zum Sieger!" }
quests[24804] = { id = 24804, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungewöhnliche Düfte", description = "Irgendetwas stimmt nicht mit dieser Chemiemanufaktur Krone. Dampfdruck hat ein Auge darauf geworfen, aber wir könnten noch ein paar mehr gebrauchen.\n\nBegebt Euch nach Sturmwind, wenn Ihr uns helfen wollt. Inspektor Snip Schnappbolz leitet die Untersuchung dort und er kann jede Hilfe gebrauchen, die er kriegen kann.", sourceObjective = "Meldet Euch bei Inspektor Snip Schnappbolz in Sturmwind.", completion = "Hey, habt Ihr etwas Zeit mitgebracht? Ich könnte jemanden wie Euch gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24805] = { id = 24805, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungewöhnliche Düfte", description = "Irgendetwas stimmt nicht mit dieser Chemiemanufaktur Krone. Dampfdruck hat ein Auge darauf geworfen, aber wir könnten noch ein paar mehr gebrauchen.\n\nBegebt Euch nach Orgrimmar, wenn Ihr uns helfen wollt. Detektiv Snap Schnappbolz leitet die Untersuchung dort und er kann jede Hilfe gebrauchen, die er kriegen kann.", sourceObjective = "Meldet Euch bei Detektiv Snap Schnappbolz in Orgrimmar.", completion = "Hey, habt Ihr etwas Zeit mitgebracht? Ich könnte jemanden wie Euch gut gebrauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[24806] = { id = 24806, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mehr Glück beim nächsten Mal" }
quests[24807] = { id = 24807, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winnoa Kiefernwald", description = "Obwohl wir hier einiges erreicht haben, wäre es eine Tragödie, wenn ein Teil dieser Verderbnis unserer Aufmerksamkeit entgangen wäre. Die Tunnel der Höhlen des Wehklagens erstrecken sich unter dem gesamten Brachland und wenn noch ein weiterer Punkt ungezähmter Energie sich einen Weg an die Oberfläche gebahnt hat...\n\nIhr habt allerdings genug für mich getan. Ich möchte Euch nur noch darum bitten, einen Druidenfreund von mir wissen zu lassen, was hier geschehen ist. Ihr findet Winnoa Kiefernwald an der Vendettakuppe südwestlich von hier.", sourceObjective = "Sprecht mit Winnoa Kiefernwald an der Vendettakuppe im Südlichen Brachland.", completion = "Ich konnte das, was sich abgespielt hat, von hier aus spüren, {class}. Mir standen alle Haare zu Berge.\n\nIch bin überglücklich zu hören, dass es Euch gelungen ist, das Grauen zurückzudrängen und ich werde ganz bestimmt das Gebiet durchsuchen, um alle herumstreunenden, mutierten Kreaturen zu finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[24812] = { id = 24812, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Keine Gnade mehr", description = "Die Naga haben unserem Volk schreckliches angetan. Die Zeit, ihnen Gnade zu zeigen, ist lang vorbei.\n\nGeht in die Höhle und tötet alle Naga, die Ihr dort findet. Jeder Naga, der heute stirbt, ist einer weniger, der uns später überraschen kann. Ich vertraue darauf, dass Ihr gründlich seid.", sourceObjective = "Tötet 12 Gallschuppennaga.", completion = "Gut gekämpft, junger {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[24813] = { id = 24813, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Territorialer Fetisch", description = "Das ist kein halbherziger Gegenangriff. Wir haben vor, jede einzelne Naga zu töten und alles zu tun, damit sie nicht zurückkehren wollen.\n\nIch will, dass Ihr diese Fetische auf jede Gallschuppenflagge setzt, die Ihr in der Höhle findet. Das sollte eine klare Aussage darüber sein, was wir von ihrer Anwesenheit hier halten. Und mehr noch: Die Magie in diesen Fetischen wird alle Gallschuppen schwächen, die sich nähern, sodass sie es sich zweimal überlegen werden, ob sie auf unserer Insel bleiben wollen.", sourceObjective = "Platziert 8 Territorialfetische auf Gallschuppenflaggen.", completion = "Das sollte sie aufhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24814] = { id = 24814, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein uralter Feind", description = "Die Seehexe ist hier, oben auf genau dieser Insel. Wir haben lange auf diese Gelegenheit zur Rache gewartet, und Ihr werdet die Ehre haben, sie zu nutzen.\n\nTrefft Euch mit Vol'jin auf der Rampe im Nordosten. Lasst es ihn wissen, wenn Ihr bereit seid, Euch in die Schlacht zu stürzen.", sourceObjective = "Sprecht mit Vol'Jin in der Bucht der Gallschuppen und helft ihm, Zar'jira die Seehexe zu töten.", completion = "Die Macht, die freigesetzt wurde, als die Seehexe starb, war immens. Ich kann diese Macht benutzen, um eine Vision von weit entfernten Orten heraufzubeschwören.\n\nSeht her, Neuling. Ich möchte, dass Ihr hier seid, wenn ich mit Thrall in Kontakt trete. Vielleicht gewinnt auch Ihr dadurch Einsicht.", sourceObjectiveStatus = "unverified-source-field" }
quests[24815] = { id = 24815, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wählt Euren Weg", sourceObjective = "Um für die Sünden, die ich als Ritter des Lichkönigs begangen habe, Sühne zu leisten, habe ich mich der Herstellung von Ringen der Macht für unsere Brüder und Schwestern verschrieben, die sie in der Schlacht verwenden können.\n\nIhr habt Euch beim Kampf gegen die Geißel als wertvoller Verbündeter erwiesen, {name}. Wenn Eure Hingabe weiter fortbesteht, kann ich den ursprünglichen Entwurf des Rings verbessern.\n\nWählt Euren Weg mit Bedacht. Ein Sinneswandel wird seinen Preis kosten.", sourceObjectiveStatus = "unverified-source-field" }
quests[24816] = { id = 24816, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wer ist jetzt an der Spitze der Nahrungskette?", description = "Gut, gut, vielleicht war diese Sache mit den Eiern doch nicht ganz ausgereift. Wer hat Lust auf Haifleisch?\n\nEs gibt da nur ein kleines Problem. Nun, eigentlich eher ein großes Problem. Ein RICHTIG großes Problem: Den Hammer!\n\nAber natürlich habe ich eine brillante Idee. Schwimmt hinaus in die Meerenge namens Bedrängnis im Westen und besorgt uns ein paar Haiteile. Gebt Sie meiner Assistentin Greely. Ich bin viel zu wichtig, um mir die Hände an diesen Details schmutzig zu machen.", sourceObjective = "Sammelt 5 Haiteile.", progress = "{name}, seid nachsichtig mit Wurfhammer. Er ist ein Genie, aber er hat ein sehr schwaches Ego.", completion = "Die sind perfekt! Jetzt müssen wir nur noch die Haiteile und die übriggebliebenen Roboteile des Mechahuhns kombinieren, und schwuppdiwupp haben wir ein Tauchboot, mit dem Ihr uns diesen lästigen Hammer vom Leib schaffen könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[24817] = { id = 24817, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Goblin im Haipelz", description = "Wir haben die Überreste des Mechahuhns mit diesen Haiteilen kombiniert und daraus das großartigste Kampftauchboot aller Zeiten gebaut: den dampfbetriebenen Mechahai-X!\n\nHobart und ich wollen, dass Ihr das Ruder übernehmt, {name}. Geht nach Westen ins Wasser und aktiviert die Steuerung für den Mechahai-X. Ihr müsst den Hammer töten, wenn wir auch nur die geringste Chance haben wollen, die natürlichen Ressourcen der Meerenge im vollen Maße auszuschöpfen!", sourceObjective = "Aktiviert die Steuerung des dampfbetriebenen Mechahai-X und benutzt ihn dann, um den Hammer zu töten.", progress = "Diese abartig riesige Monstrosität von einem Hai ist noch nicht tot! Muss ich denn alles selber machen?", completion = "Ausgezeichnete Arbeit, mein Junge! Die Instastadt ist gerettet, und das Bilgewasserkartell wird wieder Profit machen, dank meines überragenden Intellekts und meines unglaublichen Ingenieurswissens!", sourceObjectiveStatus = "unverified-source-field" }
quests[24819] = { id = 24819, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel", progress = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, {name}?", completion = "Möget Ihr finden, wonach Ihr suchet, Schwester." }
quests[24820] = { id = 24820, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel" }
quests[24821] = { id = 24821, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gesinnungswandel", progress = "Seid Ihr im Zweifel über den Weg, den Ihr eingeschlagen habt, {name}?", completion = "Möget Ihr finden, wonach Ihr suchet, Bruder." }
