quests[24828] = { id = 24828, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Zerstörung", progress = "Ihr wollt also tatsächlich weiter dem Weg der Zerstörung folgen, {name}?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
quests[24829] = { id = 24829, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Zerstörung", progress = "Ihr wollt also tatsächlich weiter dem Weg der Zerstörung folgen, {name}?", completion = "Ihr seid ein wahrer Champion unserer Sache, {name}. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nDer Feind spricht Euren Namen nur flüsternd aus, denn er weiß, dass Ihr eine Macht seid, mit der er rechnen muss.\n\nNehmt dieses bescheidene Geschenk als Dank für Eure vielen Triumphe an." }
quests[24830] = { id = 24830, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Weisheit", progress = "Ihr wollt also tatsächlich weiter dem Weg der Weisheit folgen, {name}?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
quests[24831] = { id = 24831, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Weisheit", progress = "Ihr wollt also tatsächlich weiter dem Weg der Weisheit folgen, {name}?", completion = "Ihr seid ein wahrer Champion unserer Sache, {name}. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nIhr seid eine Bastion der Weisheit und unsere Verbündeten sprechen von Euch mit größter Verehrung. Viele von ihnen schulden Euch ihr Leben.\n\nNehmt dieses bescheidene Geschenk als Dank für Eure vielen Triumphe an." }
quests[24832] = { id = 24832, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Vergeltung", progress = "Ihr wollt also tatsächlich weiter dem Weg der Vergeltung folgen, {name}?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
quests[24833] = { id = 24833, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg der Vergeltung", progress = "Ihr wollt also tatsächlich weiter dem Weg der Vergeltung folgen, {name}?", completion = "Ihr seid ein wahrer Champion unserer Sache, {name}. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nEs wird gemunkelt, dass die Lakaien der Geißel Euch mehr fürchten als den Lichkönig selber.\n\nNehmt dieses bescheidene Geschenk als Dank für Eure vielen Triumphe an." }
quests[24834] = { id = 24834, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Mutes", progress = "Ihr wollt also tatsächlich weiter dem Weg des Mutes folgen, {name}?", completion = "Ihr stellt Euren Wert wieder unter Beweis, {name}. Nehmt dies, nicht als Geschenk, sondern als Werkzeug im Kampf gegen die Geißel." }
quests[24835] = { id = 24835, flavor = "source-reference", locale = "deDE", source = "MultiLanguage cata 868743d847392a43bf3b353501432d64db8b8820", sourceFlavor = "cata", sourceRevision = "868743d847392a43bf3b353501432d64db8b8820", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weg des Mutes", progress = "Ihr wollt also tatsächlich weiter dem Weg des Mutes folgen, {name}?", completion = "Ihr seid ein wahrer Champion unserer Sache, {name}. Niemand kann für sich beanspruchen, den Kampf mit mehr Hingabe zu unterstützen als Ihr.\n\nIhr seid eine Quelle der Inspiration für unsere Verbündeten und Euer unerschütterlicher Mut lässt selbst die erfahrensten Generäle des Feindes innehalten.\n\nNehmt dieses bescheidene Geschenk als Dank für Eure vielen Triumphe an." }
